-- Syllabus gap-filling MCQs: CHE-6001..6104, PHY-6001..6078, BIO-6001..6038 (220 questions).
-- Every learning objective of the PMDC MDCAT 2025 curriculum and the NUMS MDCAT 2026 syllabus was checked against the
-- live bank; these questions cover objectives that had no questions or only a few (positive rays, gas laws and absolute
-- zero, kinetic theory, solids, first law and internal energy, alkynes, sulphonation, Friedel-Crafts, naming, adhesives
-- and dyes; graphs and projectiles, collisions, speed of sound and Laplace correction, molar specific heats, fields of
-- point charges and sheets, maximum power transfer, transformers, PN junctions; STDs, plant and animal cells, origin of
-- life, recombinant vaccines, discovery of viruses, photosynthesis factors, cyclic photophosphorylation), plus the few
-- Biology 11 and Physics 11 textbook pages that had no question yet. Topics missing from the PECTAA books are written
-- from standard references; the source column names the syllabus objective. Original questions in the bank's template.
-- Own id blocks (6001 up), so the question counters are left alone. Not in the free set.
-- questions.chapter is the MDCAT chapter, or the AKU chapter for questions off the PMDC syllabus (mdcat = 0).
-- NUMS rows only where the NUMS 2026 syllabus names the topic; every question is in the AKU bank; FSc rows only where
-- the PECTAA textbook chapter teaches the topic.

-- Inserted in batches of 20 to stay under D1's statement size limit.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-6001', 'Atomic structure', 'Positive rays', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 2.1; NUMS MDCAT 2026 Chemistry 2.1', 'Positive rays (canal rays) were first observed in a discharge tube with a perforated cathode by', '["J. J. Thomson", "E. Goldstein", "Ernest Rutherford", "James Chadwick"]', 1, 'Goldstein (1886) saw glowing rays passing backwards through holes in the cathode and called them canal rays; they were later shown to be positively charged.', '{"0": "Thomson measured e/m of cathode rays and later analysed positive rays, but did not discover them.", "2": "Rutherford proposed the nuclear atom and named the proton later.", "3": "Chadwick discovered the neutron (1932)."}'),
  ('CHE-6002', 'Atomic structure', 'Positive rays', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 2.1; NUMS MDCAT 2026 Chemistry 2.1', 'In a discharge tube, positive rays are produced when', '["cathode rays knock electrons out of the gas atoms or molecules in the tube", "positive ions are emitted from the hot anode", "the cathode releases protons from its nuclei", "neutrons in the gas decay into protons"]', 0, 'Fast cathode-ray electrons collide with gas particles and remove electrons from them; the positive ions left behind move towards the cathode and through its holes as positive rays.', '{"1": "The anode does not emit the ions; they come from the gas.", "2": "The cathode metal is not the source; positive rays depend on the gas in the tube.", "3": "No nuclear decay is involved in a discharge tube."}'),
  ('CHE-6003', 'Atomic structure', 'Positive rays', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 2.1; NUMS MDCAT 2026 Chemistry 2.1', 'The e/m (charge-to-mass) ratio of positive rays is greatest when the discharge tube contains', '["helium", "neon", "oxygen", "hydrogen"]', 3, 'e/m is largest for the lightest positive ion, H⁺. The positive particle from hydrogen gas, with the highest e/m of all positive rays, was identified as the proton.', '{"0": "He⁺ is about four times heavier than H⁺, so its e/m is smaller.", "1": "Ne⁺ is about twenty times heavier than H⁺.", "2": "O⁺ or O₂⁺ is much heavier than H⁺."}'),
  ('CHE-6004', 'Atomic structure', 'Positive rays', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 2.1; NUMS MDCAT 2026 Chemistry 2.1', 'Which property of positive rays is DIFFERENT from that of cathode rays?', '["They travel in straight lines.", "They are deflected by electric and magnetic fields.", "Their e/m value depends on the gas in the discharge tube.", "They are made of material particles that have mass."]', 2, 'Cathode rays (electrons) have the same e/m whatever gas is used, but positive rays are ions of the gas, so their e/m changes with the gas.', '{"0": "Both kinds of rays travel in straight lines.", "1": "Both are deflected, though in opposite directions.", "3": "Both consist of particles with mass."}'),
  ('CHE-6005', 'Atomic structure', 'Positive rays', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 2.1; NUMS MDCAT 2026 Chemistry 2.1', 'Compared with cathode rays in the same electric field, positive rays are deflected', '["towards the positive plate and by a larger amount", "towards the negative plate and by a much smaller amount", "towards the negative plate and by the same amount", "not at all, because they are neutral"]', 1, 'Positive rays carry positive charge, so they bend towards the negative plate; their particles are thousands of times heavier than electrons, so they bend far less.', '{"0": "That describes neither ray: cathode rays bend towards the positive plate.", "2": "The heavier ions bend much less than electrons.", "3": "Positive rays are charged ions, not neutral particles."}'),
  ('CHE-6006', 'Atomic structure', 'Properties of the proton', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 2.1; NUMS MDCAT 2026 Chemistry 2.1', 'The mass of a proton is about how many times the mass of an electron?', '["1836", "1/1836", "18.36", "183.6"]', 0, 'A proton has mass 1.6726 × 10⁻²⁷ kg and an electron 9.11 × 10⁻³¹ kg; the ratio is about 1836.', '{"1": "This inverts the ratio; the proton is the heavier particle.", "2": "Far too small; check the powers of ten.", "3": "Still ten times too small."}'),
  ('CHE-6007', 'Atomic structure', 'Hydrogen spectrum', 'easy', 'PMDC MDCAT 2025 Chemistry 2.6; NUMS MDCAT 2026 Chemistry 2.6', 'The visible (Balmer) lines of the hydrogen spectrum are produced when the electron falls from higher orbits to the orbit with', '["n = 1", "n = 3", "n = 4", "n = 2"]', 3, 'Balmer lines end on n = 2 and lie in the visible region. Lyman lines end on n = 1 (ultraviolet) and Paschen lines on n = 3 (infrared).', '{"0": "Transitions to n = 1 give the ultraviolet Lyman series.", "1": "Transitions to n = 3 give the infrared Paschen series.", "2": "Transitions to n = 4 give the infrared Brackett series."}'),
  ('CHE-6008', 'Atomic structure', 'Bohr model', 'moderate', 'PMDC MDCAT 2025 Chemistry 2.6; NUMS MDCAT 2026 Chemistry 2.6', 'In Bohr''s model, the energy of the electron in the n-th orbit of hydrogen is −13.6/n² eV. What is its energy in the second orbit?', '["−13.6 eV", "−6.8 eV", "−3.4 eV", "−1.51 eV"]', 2, 'E₂ = −13.6/2² = −13.6/4 = −3.4 eV.', '{"0": "This is the energy of the first orbit (n = 1).", "1": "This divides by n instead of n².", "3": "This is the energy of the third orbit (−13.6/9)."}'),
  ('CHE-6009', 'Atomic structure', 'Bohr model', 'moderate', 'PMDC MDCAT 2025 Chemistry 2.6; NUMS MDCAT 2026 Chemistry 2.6', 'The radius of the first Bohr orbit of hydrogen is 0.529 Å and rₙ = 0.529 n² Å. The radius of the third orbit is', '["1.59 Å", "4.76 Å", "2.12 Å", "0.176 Å"]', 1, 'r₃ = 0.529 × 3² = 0.529 × 9 ≈ 4.76 Å.', '{"0": "This multiplies by n instead of n².", "2": "This is the radius of the second orbit (0.529 × 4).", "3": "This divides by n instead of multiplying by n²."}'),
  ('CHE-6010', 'Atomic structure', 'Hydrogen spectrum', 'easy', 'PMDC MDCAT 2025 Chemistry 2.6; NUMS MDCAT 2026 Chemistry 2.6', 'Hydrogen gas in a discharge tube gives a line spectrum rather than a continuous spectrum because', '["the electron in the atom can have only certain fixed energies", "hydrogen atoms contain only one electron", "hydrogen molecules absorb all visible light", "the electron moves in a spiral towards the nucleus"]', 0, 'Electron energies in the atom are quantised, so a jump between two allowed levels releases a photon of one exact energy, E = hν, giving sharp lines.', '{"1": "Atoms with many electrons also give line spectra; the reason is quantised energy, not the number of electrons.", "2": "Hydrogen is colourless; it does not absorb all visible light.", "3": "A spiralling electron (classical picture) would give a continuous spectrum, which is not seen."}'),
  ('CHE-6011', 'States of matter', 'Kinetic molecular theory', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 3.1–3.2; NUMS MDCAT 2026 Chemistry 3.1–3.2', 'Which statement is NOT a postulate of the kinetic molecular theory of gases?', '["Gas molecules are in constant, random, straight-line motion.", "Collisions between gas molecules are perfectly elastic.", "The actual volume of gas molecules is negligible compared with the volume of the container.", "Gas molecules attract each other strongly."]', 3, 'Kinetic theory assumes there are NO attractive or repulsive forces between ideal gas molecules. Real gases do attract weakly, which is one reason they deviate from ideal behaviour.', '{"0": "This is a postulate of the theory.", "1": "This is a postulate: no kinetic energy is lost in collisions.", "2": "This is a postulate of the theory."}'),
  ('CHE-6012', 'States of matter', 'Kinetic molecular theory', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 3.1–3.2; NUMS MDCAT 2026 Chemistry 3.1–3.2', 'According to the kinetic molecular theory, the average kinetic energy of gas molecules is directly proportional to the', '["Celsius temperature", "molar mass of the gas", "absolute temperature", "volume of the container"]', 2, 'Average kinetic energy = (3/2)kT, so it depends only on the absolute (Kelvin) temperature.', '{"0": "A Celsius temperature of 0 °C does not mean zero kinetic energy; only the Kelvin scale is proportional.", "1": "At the same temperature all gases have the same average kinetic energy, whatever their molar mass.", "3": "Volume does not change the average kinetic energy at constant temperature."}'),
  ('CHE-6013', 'States of matter', 'Kinetic molecular theory', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 3.1–3.2; NUMS MDCAT 2026 Chemistry 3.1–3.2', 'According to kinetic theory, the pressure exerted by a gas is due to', '["attraction between gas molecules", "collisions of the molecules with the walls of the container", "the weight of the gas molecules", "the volume occupied by the molecules"]', 1, 'Each molecule that strikes a wall changes momentum, exerting a force; the total force per unit area of countless collisions is the gas pressure.', '{"0": "Attractions actually reduce the pressure of a real gas slightly.", "2": "The weight of gas molecules is negligible.", "3": "The molecules'' own volume is assumed negligible."}'),
  ('CHE-6014', 'States of matter', 'Kinetic molecular theory', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 3.1–3.2; NUMS MDCAT 2026 Chemistry 3.1–3.2', 'Samples of H₂ and O₂ are at the same temperature. Which statement is correct?', '["Both have the same average kinetic energy, but H₂ molecules move faster on average.", "O₂ molecules have the greater average kinetic energy.", "Both have the same average speed.", "H₂ molecules have greater average kinetic energy and greater speed."]', 0, 'Average kinetic energy depends only on temperature, so it is equal. Since ½mv² is equal, the lighter H₂ molecules must have the higher average speed.', '{"1": "Average kinetic energy depends only on temperature.", "2": "Equal kinetic energies with unequal masses means unequal speeds.", "3": "Their average kinetic energies are equal at the same temperature."}'),
  ('CHE-6015', 'States of matter', 'Boyle''s law', 'easy', 'PMDC MDCAT 2025 Chemistry 3.4; NUMS MDCAT 2026 Chemistry 3.4', 'A gas occupies 2.0 dm³ at 1.0 atm. At constant temperature it is compressed to 0.50 dm³. Its new pressure is', '["0.25 atm", "2.0 atm", "1.0 atm", "4.0 atm"]', 3, 'Boyle''s law: P₁V₁ = P₂V₂, so P₂ = (1.0 × 2.0)/0.50 = 4.0 atm.', '{"0": "This multiplies the pressure by the volume ratio the wrong way round.", "1": "The volume fell to one quarter, so the pressure rises fourfold, not twofold.", "2": "Pressure must change when volume changes at constant temperature."}'),
  ('CHE-6016', 'States of matter', 'Boyle''s law', 'moderate', 'PMDC MDCAT 2025 Chemistry 3.4; NUMS MDCAT 2026 Chemistry 3.4', 'For a fixed amount of gas at constant temperature, which graph is a straight line passing through the origin?', '["P against V", "PV against P", "P against 1/V", "V against T"]', 2, 'Since P = k/V, P is directly proportional to 1/V, giving a straight line through the origin.', '{"0": "P against V is a hyperbola (curve).", "1": "PV against P is a horizontal straight line, not one through the origin.", "3": "V against T is Charles''s law at constant pressure, not Boyle''s law."}'),
  ('CHE-6017', 'States of matter', 'Boyle''s law', 'moderate', 'PMDC MDCAT 2025 Chemistry 3.4; NUMS MDCAT 2026 Chemistry 3.4', 'In Boyle''s law, PV = k. For a given mass of gas, the value of k increases when', '["the pressure is increased", "the temperature is increased", "the volume is decreased", "the gas is compressed slowly"]', 1, 'k = nRT, so for a fixed amount of gas k depends only on temperature; a higher temperature gives a larger k (a higher isotherm).', '{"0": "Changing pressure at constant temperature changes V, not the product PV.", "2": "Changing volume changes P, but PV stays the same.", "3": "Slow compression at constant temperature leaves PV unchanged."}'),
  ('CHE-6018', 'States of matter', 'Charles''s law', 'moderate', 'PMDC MDCAT 2025 Chemistry 3.5; NUMS MDCAT 2026 Chemistry 3.5', 'A gas occupies 300 cm³ at 27 °C. At constant pressure, what is its volume at 127 °C?', '["400 cm³", "1411 cm³", "225 cm³", "600 cm³"]', 0, 'Charles''s law with Kelvin temperatures: V₂ = V₁T₂/T₁ = 300 × 400/300 = 400 cm³.', '{"1": "This uses Celsius temperatures (300 × 127/27), which is not allowed.", "2": "This inverts the temperature ratio.", "3": "Volume is not doubled; the absolute temperature rises only from 300 K to 400 K."}'),
  ('CHE-6019', 'States of matter', 'Charles''s law', 'moderate', 'PMDC MDCAT 2025 Chemistry 3.5; NUMS MDCAT 2026 Chemistry 3.5', 'A gas occupies 273 cm³ at 0 °C. At constant pressure, its volume at 10 °C will be', '["263 cm³", "273 cm³", "2730 cm³", "283 cm³"]', 3, 'At constant pressure, a gas expands by 1/273 of its volume at 0 °C for every 1 °C rise; 273 cm³ gains 10 cm³, giving 283 cm³ (equivalently 273 × 283/273).', '{"0": "The volume increases on heating, it does not decrease.", "1": "Volume changes with temperature at constant pressure.", "2": "This treats V as proportional to the Celsius temperature."}'),
  ('CHE-6020', 'States of matter', 'Absolute zero', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 3.6; NUMS MDCAT 2026 Chemistry 3.6', 'Absolute zero, the zero of the Kelvin scale, is equal to', '["−100 °C", "0 °C", "−273.15 °C", "−373.15 °C"]', 2, '0 K = −273.15 °C (often rounded to −273 °C). The Kelvin and Celsius degrees are the same size.', '{"0": "This value has no special significance.", "1": "0 °C is the freezing point of water, 273.15 K.", "3": "This subtracts 100 from the correct value."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-6021', 'States of matter', 'Absolute zero', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 3.6; NUMS MDCAT 2026 Chemistry 3.6', 'When the volume–temperature graph of a gas at constant pressure is extended to lower temperatures, it meets the temperature axis at −273.15 °C. Which statement about this temperature is correct?', '["At this temperature the molecules move fastest.", "It is the lowest temperature possible; it has never actually been reached.", "Every gas would double its volume at this temperature.", "It is the boiling point of liquid nitrogen."]', 1, 'At absolute zero an ideal gas would have zero volume and its molecules minimum kinetic energy. No lower temperature is possible, and it can be approached but not reached in practice.', '{"0": "Molecular motion is at its minimum, not maximum, at absolute zero.", "2": "The volume of an ideal gas would theoretically become zero, not double.", "3": "Liquid nitrogen boils at about −196 °C (77 K)."}'),
  ('CHE-6022', 'States of matter', 'Absolute zero', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 3.6; NUMS MDCAT 2026 Chemistry 3.6', 'A temperature of −23 °C on the Kelvin scale is', '["250 K", "−296 K", "23 K", "296 K"]', 0, 'T(K) = t(°C) + 273 = −23 + 273 = 250 K.', '{"1": "Kelvin temperatures are never negative.", "2": "This ignores the 273 offset.", "3": "This adds 23 instead of subtracting it."}'),
  ('CHE-6023', 'States of matter', 'Absolute zero', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 3.6; NUMS MDCAT 2026 Chemistry 3.6', 'Charles''s law predicts zero volume at absolute zero, yet no real gas ever shows zero volume because', '["real gases expand on cooling", "real gas molecules have no mass", "the pressure of a real gas becomes infinite on cooling", "real gases condense to liquids or solids before absolute zero is reached"]', 3, 'Real molecules occupy space and attract each other, so every real gas liquefies or solidifies at a temperature above 0 K; the zero-volume prediction applies only to an ideal gas.', '{"0": "Gases contract, not expand, on cooling at constant pressure.", "1": "Real molecules do have mass; mass is not the reason.", "2": "At constant pressure the pressure does not change."}'),
  ('CHE-6024', 'States of matter', 'Gas constant', 'moderate', 'PMDC MDCAT 2025 Chemistry 3.7–3.9; NUMS MDCAT 2026 Chemistry 3.7–3.9', 'Which of these is NOT a correct value of the gas constant R?', '["8.314 J K⁻¹ mol⁻¹", "0.0821 dm³ atm K⁻¹ mol⁻¹", "62.4 dm³ atm K⁻¹ mol⁻¹", "1.987 cal K⁻¹ mol⁻¹"]', 2, 'R = 8.314 J K⁻¹ mol⁻¹ = 0.0821 dm³ atm K⁻¹ mol⁻¹ = 1.987 cal K⁻¹ mol⁻¹ = 62.4 dm³ mmHg (torr) K⁻¹ mol⁻¹. The value 62.4 goes with mmHg, not atm.', '{"0": "This is the SI value of R.", "1": "This is R in dm³ atm units.", "3": "This is R in calories (8.314/4.184)."}'),
  ('CHE-6025', 'States of matter', 'Avogadro''s law', 'easy', 'PMDC MDCAT 2025 Chemistry 3.7–3.9; NUMS MDCAT 2026 Chemistry 3.7–3.9', 'What volume does 4.0 g of helium occupy at STP? (He = 4)', '["5.6 dm³", "22.4 dm³", "11.2 dm³", "89.6 dm³"]', 1, '4.0 g of He is 1 mol, and by Avogadro''s law 1 mol of any ideal gas occupies 22.4 dm³ at STP.', '{"0": "This is the volume of 0.25 mol.", "2": "This treats helium as diatomic (He₂ = 8 g mol⁻¹).", "3": "This multiplies by the mass instead of using moles."}'),
  ('CHE-6026', 'States of matter', 'Ideal gas equation', 'moderate', 'PMDC MDCAT 2025 Chemistry 3.7–3.9; NUMS MDCAT 2026 Chemistry 3.7–3.9', 'How many moles of an ideal gas are in a 24.63 dm³ container at 2.0 atm and 300 K? (R = 0.0821 dm³ atm K⁻¹ mol⁻¹)', '["2.0 mol", "0.50 mol", "1.0 mol", "4.0 mol"]', 0, 'n = PV/RT = (2.0 × 24.63)/(0.0821 × 300) = 49.26/24.63 = 2.0 mol.', '{"1": "This inverts the pressure term.", "2": "This ignores the pressure of 2.0 atm.", "3": "This doubles the pressure twice."}'),
  ('CHE-6027', 'States of matter', 'Real and ideal gases', 'easy', 'PMDC MDCAT 2025 Chemistry 3.7–3.9; NUMS MDCAT 2026 Chemistry 3.7–3.9', 'A real gas behaves most like an ideal gas at', '["high pressure and low temperature", "high pressure and high temperature", "low pressure and low temperature", "low pressure and high temperature"]', 3, 'At low pressure the molecules are far apart (their own volume is negligible) and at high temperature their kinetic energy overwhelms intermolecular attractions.', '{"0": "These conditions cause the largest deviations and favour liquefaction.", "1": "High pressure crowds molecules so their volume matters.", "2": "Low temperature lets attractive forces act."}'),
  ('CHE-6028', 'States of matter', 'Real and ideal gases', 'moderate', 'PMDC MDCAT 2025 Chemistry 3.7–3.9; NUMS MDCAT 2026 Chemistry 3.7–3.9', 'Van der Waals traced the deviation of real gases from ideal behaviour to two faulty assumptions of kinetic theory. These are that gas molecules', '["move randomly and collide elastically", "have equal masses and equal speeds", "have negligible volume and do not attract each other", "obey Newton''s laws and have kinetic energy"]', 2, 'Real molecules do occupy volume (important at high pressure) and do attract each other (important at low temperature); van der Waals corrected both terms in his equation.', '{"0": "These assumptions are reasonable for real gases too.", "1": "Kinetic theory does not assume equal speeds; speeds are distributed.", "3": "These are not the assumptions that fail."}'),
  ('CHE-6029', 'States of matter', 'Real and ideal gases', 'moderate', 'PMDC MDCAT 2025 Chemistry 3.7–3.9; NUMS MDCAT 2026 Chemistry 3.7–3.9', 'Under ordinary conditions, which gas shows the smallest deviation from ideal behaviour?', '["NH₃", "He", "SO₂", "H₂O vapour"]', 1, 'Helium atoms are small, non-polar and have very weak London forces, so it behaves almost ideally; polar molecules such as NH₃, SO₂ and H₂O attract each other strongly.', '{"0": "NH₃ is polar and hydrogen-bonded, so it deviates strongly and liquefies easily.", "2": "SO₂ is polar and easily liquefied.", "3": "Water molecules hydrogen bond strongly."}'),
  ('CHE-6030', 'States of matter', 'Anomalous behaviour of water', 'easy', 'PMDC MDCAT 2025 Chemistry 4.4; NUMS MDCAT 2026 Chemistry 4.4', 'Liquid water has its maximum density at about', '["4 °C", "0 °C", "25 °C", "100 °C"]', 0, 'On cooling, water contracts until 4 °C; below this, hydrogen bonds begin to hold molecules in a more open arrangement and the water expands, so density is greatest at 4 °C.', '{"1": "At 0 °C water is less dense than at 4 °C; ice is less dense still.", "2": "Water at 25 °C is less dense than at 4 °C.", "3": "Near its boiling point water is at its least dense as a liquid."}'),
  ('CHE-6031', 'States of matter', 'Anomalous behaviour of water', 'easy', 'PMDC MDCAT 2025 Chemistry 4.4; NUMS MDCAT 2026 Chemistry 4.4', 'Ice floats on liquid water because', '["ice contains trapped air bubbles", "ice molecules are lighter than water molecules", "water molecules repel each other strongly in the liquid", "in ice, hydrogen bonds hold the molecules in an open cage-like lattice with empty spaces"]', 3, 'Each water molecule in ice is hydrogen bonded tetrahedrally to four others, forming an open hexagonal lattice; this makes ice about 9% less dense than liquid water.', '{"0": "Pure, bubble-free ice also floats.", "1": "Molecules in ice and water are identical H₂O.", "2": "Water molecules attract each other by hydrogen bonds."}'),
  ('CHE-6032', 'States of matter', 'Anomalous behaviour of water', 'moderate', 'PMDC MDCAT 2025 Chemistry 4.4; NUMS MDCAT 2026 Chemistry 4.4', 'In a very cold winter, fish in a deep lake survive under a sheet of ice mainly because', '["ice is a good conductor of heat", "the water below the ice boils", "water at about 4 °C, being densest, sinks and stays at the bottom while the lake freezes from the top", "fish produce enough heat to melt the ice"]', 2, 'Water at 4 °C is densest and sinks. Colder water and then ice stay on top, and the ice layer insulates the water below, which stays liquid.', '{"0": "Ice is a poor conductor of heat, which is why it insulates the water beneath.", "1": "Water under ice is near 4 °C, far from boiling.", "3": "Fish are cold-blooded and produce little heat."}'),
  ('CHE-6033', 'States of matter', 'Ionic crystals', 'moderate', 'PMDC MDCAT 2025 Chemistry 5.1–5.4; NUMS MDCAT 2026 Chemistry 5.1–5.4', 'The coordination number and therefore the shape of an ionic crystal depend largely on the', '["colour of the ions", "ratio of the radius of the cation to that of the anion", "melting point of the crystal", "number of neutrons in the ions"]', 1, 'The radius ratio r₊/r₋ decides how many anions can pack around a cation; together with the charges (ratio) of the ions and how they pack, it fixes the crystal structure.', '{"0": "Colour has nothing to do with packing.", "2": "The melting point is a result of the structure, not its cause.", "3": "Neutron number does not affect ionic size or packing."}'),
  ('CHE-6034', 'States of matter', 'Ionic crystals', 'hard', 'PMDC MDCAT 2025 Chemistry 5.1–5.4; NUMS MDCAT 2026 Chemistry 5.1–5.4', 'In NaCl each Na⁺ is surrounded by 6 Cl⁻ ions, but in CsCl each Cs⁺ is surrounded by 8 Cl⁻ ions. The main reason is that', '["Cs⁺ is larger than Na⁺, so more Cl⁻ ions fit around it", "Cs⁺ has a larger charge than Na⁺", "Cl⁻ is smaller in CsCl than in NaCl", "CsCl is a molecular crystal"]', 0, 'Cs⁺ (about 167 pm) is much larger than Na⁺ (about 102 pm), so the radius ratio is higher and eight chloride ions can touch it, giving 8:8 coordination instead of 6:6.', '{"1": "Both ions carry a +1 charge.", "2": "The chloride ion is the same size in both.", "3": "Both are ionic crystals."}'),
  ('CHE-6035', 'States of matter', 'Types of solids', 'easy', 'PMDC MDCAT 2025 Chemistry 5.1–5.4; NUMS MDCAT 2026 Chemistry 5.1–5.4', 'Which of these is a molecular solid?', '["Sodium chloride", "Diamond", "Copper", "Solid iodine"]', 3, 'Iodine crystals contain separate I₂ molecules held by weak London forces, so iodine is soft, sublimes easily and does not conduct electricity.', '{"0": "NaCl is an ionic solid.", "1": "Diamond is a covalent network solid.", "2": "Copper is a metallic solid."}'),
  ('CHE-6036', 'States of matter', 'Types of solids', 'easy', 'PMDC MDCAT 2025 Chemistry 5.1–5.4; NUMS MDCAT 2026 Chemistry 5.1–5.4', 'Compared with ionic solids, molecular solids generally have low melting points because', '["they contain free electrons", "their particles carry large charges", "their molecules are held together by weak intermolecular forces", "they have no fixed shape"]', 2, 'Melting a molecular solid only overcomes weak intermolecular forces, whereas an ionic solid needs strong electrostatic attractions between ions to be broken.', '{"0": "Free electrons are a feature of metals.", "1": "Molecules are neutral; charged particles are found in ionic solids.", "3": "Molecular solids such as ice and iodine are crystalline with definite shapes."}'),
  ('CHE-6037', 'States of matter', 'Crystal lattice', 'easy', 'PMDC MDCAT 2025 Chemistry 5.1–5.4; NUMS MDCAT 2026 Chemistry 5.1–5.4', 'The smallest repeating part of a crystal lattice, which when repeated in three dimensions builds the whole lattice, is called the', '["lattice point", "unit cell", "crystal face", "isomorph"]', 1, 'A crystal lattice is a regular three-dimensional array of points representing the particles; its unit cell is the smallest block that repeats to generate it.', '{"0": "A lattice point is a single position, not a repeating block.", "2": "A face is a flat outer surface of the crystal.", "3": "Isomorphs are different substances with the same crystal form."}'),
  ('CHE-6038', 'States of matter', 'Crystalline solids', 'moderate', 'PMDC MDCAT 2025 Chemistry 5.1–5.4; NUMS MDCAT 2026 Chemistry 5.1–5.4', 'Which property shows that a solid is crystalline rather than amorphous?', '["It melts sharply at a definite temperature.", "It is hard.", "It is transparent.", "It softens gradually over a range of temperature."]', 0, 'The regular arrangement of particles in a crystalline solid means all bonds break at the same temperature, giving a sharp melting point. Amorphous solids such as glass soften over a range.', '{"1": "Hardness alone does not show order; glass is hard but amorphous.", "2": "Both crystalline and amorphous solids may be transparent.", "3": "Gradual softening is typical of amorphous solids."}'),
  ('CHE-6039', 'Chemical equilibrium', 'Le Chatelier''s principle', 'easy', 'PMDC MDCAT 2025 Chemistry 6.3; NUMS MDCAT 2026 Chemistry 6.3', 'For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), what happens when the pressure is increased at constant temperature?', '["The equilibrium shifts to the left.", "There is no change in the position of equilibrium.", "The value of Kc increases.", "The equilibrium shifts to the right."]', 3, 'Increasing pressure favours the side with fewer gas molecules: 4 mol of reactant gases give 2 mol of product, so more NH₃ forms.', '{"0": "The left side has more gas molecules, so higher pressure opposes it.", "1": "The two sides have different numbers of gas moles, so pressure matters.", "2": "Kc changes only with temperature."}'),
  ('CHE-6040', 'Chemical equilibrium', 'Le Chatelier''s principle', 'easy', 'PMDC MDCAT 2025 Chemistry 6.3; NUMS MDCAT 2026 Chemistry 6.3', 'Adding a catalyst to a reaction mixture at equilibrium', '["shifts the equilibrium towards the products", "increases the value of K", "does not change the position of equilibrium, but equilibrium is reached faster", "shifts the equilibrium towards the reactants"]', 2, 'A catalyst lowers the activation energy of the forward and reverse reactions equally, so both rates rise by the same factor and the composition at equilibrium is unchanged.', '{"0": "Both directions are speeded up equally, so there is no shift.", "1": "K depends only on temperature.", "3": "There is no shift in either direction."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-6041', 'Chemical equilibrium', 'Le Chatelier''s principle', 'moderate', 'PMDC MDCAT 2025 Chemistry 6.3; NUMS MDCAT 2026 Chemistry 6.3', 'For which equilibrium does a change in pressure have NO effect on the position of equilibrium?', '["N₂O₄(g) ⇌ 2NO₂(g)", "H₂(g) + I₂(g) ⇌ 2HI(g)", "2SO₂(g) + O₂(g) ⇌ 2SO₃(g)", "PCl₅(g) ⇌ PCl₃(g) + Cl₂(g)"]', 1, 'There are 2 mol of gas on each side of H₂ + I₂ ⇌ 2HI, so neither direction reduces the pressure.', '{"0": "1 mol of gas becomes 2 mol, so pressure affects it.", "2": "3 mol of gas becomes 2 mol.", "3": "1 mol of gas becomes 2 mol."}'),
  ('CHE-6042', 'Chemical equilibrium', 'Le Chatelier''s principle', 'moderate', 'PMDC MDCAT 2025 Chemistry 6.3; NUMS MDCAT 2026 Chemistry 6.3', 'For an exothermic reaction at equilibrium, raising the temperature', '["shifts the equilibrium to the left and decreases K", "shifts the equilibrium to the right and increases K", "has no effect on K", "shifts the equilibrium to the right and decreases K"]', 0, 'Heat behaves as a product of an exothermic reaction. Adding heat favours the endothermic (reverse) direction, so less product forms at equilibrium and K becomes smaller.', '{"1": "This is what happens for an endothermic reaction.", "2": "K does change with temperature.", "3": "A right shift would increase, not decrease, K."}'),
  ('CHE-6043', 'Chemical equilibrium', 'Le Chatelier''s principle', 'moderate', 'PMDC MDCAT 2025 Chemistry 6.3; NUMS MDCAT 2026 Chemistry 6.3', 'More N₂ is added to an equilibrium mixture of N₂, H₂ and NH₃ at constant temperature. Which is correct once equilibrium is re-established?', '["The position shifts to the right and Kc increases.", "The position shifts to the left and Kc is unchanged.", "Nothing changes because N₂ is unreactive.", "The position shifts to the right and Kc is unchanged."]', 3, 'The system uses up some of the added N₂ by forming more NH₃, but because temperature is constant the equilibrium constant keeps its value.', '{"0": "Concentration changes do not alter Kc.", "1": "Adding a reactant favours the forward reaction.", "2": "N₂ takes part in the equilibrium, so adding it disturbs the system."}'),
  ('CHE-6044', 'Thermochemistry', 'First law of thermodynamics', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 8.1, 8.3–8.5; NUMS MDCAT 2026 Chemistry 8.1, 8.3–8.5', 'The first law of thermodynamics states that', '["heat always flows from a hot body to a cold body", "the entropy of the universe always increases", "energy can neither be created nor destroyed, only converted from one form to another", "all spontaneous reactions are exothermic"]', 2, 'The first law is the law of conservation of energy: ΔE = q + w, where q is heat absorbed by the system and w is work done on it.', '{"0": "This is a statement related to the second law.", "1": "This is the second law of thermodynamics.", "3": "Some spontaneous processes are endothermic, such as dissolving NH₄NO₃."}'),
  ('CHE-6045', 'Thermochemistry', 'First law of thermodynamics', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 8.1, 8.3–8.5; NUMS MDCAT 2026 Chemistry 8.1, 8.3–8.5', 'A system absorbs 50 kJ of heat and does 20 kJ of work on its surroundings. The change in its internal energy is', '["+70 kJ", "+30 kJ", "−30 kJ", "−70 kJ"]', 1, 'ΔE = q + w = (+50) + (−20) = +30 kJ. Heat absorbed is positive; work done BY the system is negative.', '{"0": "This adds the work instead of subtracting it.", "2": "The system gains more heat than the work it does, so ΔE is positive.", "3": "Both signs are wrong."}'),
  ('CHE-6046', 'Thermochemistry', 'Internal energy', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 8.1, 8.3–8.5; NUMS MDCAT 2026 Chemistry 8.1, 8.3–8.5', 'The internal energy of a system is', '["the sum of all kinetic and potential energies of the particles in the system", "only the kinetic energy of its molecules", "the heat given out in a reaction", "the work done on the system"]', 0, 'Internal energy (E or U) includes translational, rotational and vibrational kinetic energy and the potential energy of bonds and intermolecular forces. Its absolute value cannot be measured, only changes ΔE.', '{"1": "Potential energy of bonds and attractions is also included.", "2": "Heat given out is one way the internal energy can change.", "3": "Work is another way internal energy changes, not the energy itself."}'),
  ('CHE-6047', 'Thermochemistry', 'Internal energy', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 8.1, 8.3–8.5; NUMS MDCAT 2026 Chemistry 8.1, 8.3–8.5', 'In SI units, internal energy is measured in', '["watts", "kelvins", "joules per kelvin", "joules"]', 3, 'Internal energy is an energy, so its SI unit is the joule (J); molar values are given in kJ mol⁻¹.', '{"0": "The watt is a unit of power (J s⁻¹).", "1": "The kelvin is a unit of temperature.", "2": "J K⁻¹ is the unit of heat capacity and entropy."}'),
  ('CHE-6048', 'Thermochemistry', 'Internal energy', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 8.1, 8.3–8.5; NUMS MDCAT 2026 Chemistry 8.1, 8.3–8.5', 'A reaction is carried out in a sealed bomb calorimeter, so its volume is constant. The heat absorbed or released equals', '["ΔH", "zero", "ΔE", "PΔV"]', 2, 'At constant volume no expansion work is done (w = −PΔV = 0), so the first law gives qᵥ = ΔE.', '{"0": "ΔH is the heat change at constant pressure.", "1": "Heat is still exchanged; only work is zero.", "3": "PΔV is zero at constant volume."}'),
  ('CHE-6049', 'Thermochemistry', 'Internal energy and enthalpy', 'hard', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 8.1, 8.3–8.5; NUMS MDCAT 2026 Chemistry 8.1, 8.3–8.5', 'For which reaction are ΔH and ΔE equal (ΔH = ΔE + ΔnRT)?', '["N₂(g) + 3H₂(g) → 2NH₃(g)", "H₂(g) + Cl₂(g) → 2HCl(g)", "CaCO₃(s) → CaO(s) + CO₂(g)", "2H₂(g) + O₂(g) → 2H₂O(l)"]', 1, 'In H₂ + Cl₂ → 2HCl there are 2 mol of gas on both sides, so Δn = 0 and no expansion work is done: ΔH = ΔE.', '{"0": "Δn = 2 − 4 = −2.", "2": "Δn = +1 (CO₂ gas is formed).", "3": "Δn = 0 − 3 = −3, since the water is liquid."}'),
  ('CHE-6050', 'Thermochemistry', 'State functions', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 8.1, 8.3–8.5; NUMS MDCAT 2026 Chemistry 8.1, 8.3–8.5', 'Which of the following is NOT a state function?', '["Work", "Internal energy", "Enthalpy", "Pressure"]', 0, 'A state function depends only on the initial and final states. The work done depends on the path taken between those states, so it is not a state function (neither is heat).', '{"1": "ΔE depends only on the initial and final states.", "2": "Enthalpy is a state function, which is why Hess''s law works.", "3": "Pressure is a property of the state."}'),
  ('CHE-6051', 'Electrochemistry', 'Ion-electron method', 'moderate', 'NUMS MDCAT 2026 Chemistry 9.6', 'In the balanced half-equation for the reduction of MnO₄⁻ to Mn²⁺ in acidic solution, the number of electrons is', '["3", "2", "7", "5"]', 3, 'MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O. Mn goes from +7 to +2, a gain of 5 electrons.', '{"0": "Three electrons are gained when MnO₄⁻ is reduced to MnO₂ (in neutral solution).", "1": "This is the charge of Mn²⁺, not the electrons gained.", "2": "This is the oxidation number of Mn in MnO₄⁻."}'),
  ('CHE-6052', 'Electrochemistry', 'Ion-electron method', 'hard', 'NUMS MDCAT 2026 Chemistry 9.6', 'In the balanced half-equation Cr₂O₇²⁻ + xH⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O, the value of x is', '["7", "6", "14", "12"]', 2, 'Seven O atoms form 7 H₂O, which needs 14 H⁺. Check charge: −2 + 14 − 6 = +6 on the left, and 2 × (+3) = +6 on the right.', '{"0": "Seven H⁺ would supply only half the hydrogen in 7 H₂O.", "1": "This confuses H⁺ with the number of electrons.", "3": "This does not balance hydrogen or charge."}'),
  ('CHE-6053', 'Electrochemistry', 'Ion-electron method', 'hard', 'NUMS MDCAT 2026 Chemistry 9.6', 'In acidic solution MnO₄⁻ oxidises Fe²⁺ to Fe³⁺. How many moles of Fe²⁺ react with 1 mol of MnO₄⁻?', '["1", "5", "2", "8"]', 1, 'MnO₄⁻ gains 5 electrons, while each Fe²⁺ loses only 1 (Fe²⁺ → Fe³⁺ + e⁻). Balancing electrons: MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O.', '{"0": "This ignores the unequal numbers of electrons.", "2": "This does not balance the five electrons.", "3": "Eight is the number of H⁺ ions, not Fe²⁺ ions."}'),
  ('CHE-6054', 'Chemical bonding', 'Ionic character of covalent bonds', 'easy', 'PMDC MDCAT 2025 Chemistry 10.6; NUMS MDCAT 2026 Chemistry 10.6', 'Which bond has the greatest ionic character?', '["H–F", "H–I", "H–Br", "H–Cl"]', 0, 'Ionic character increases with the electronegativity difference. F is the most electronegative element, so H–F (difference about 1.9) is the most polar.', '{"1": "I has the lowest electronegativity of the halogens.", "2": "The H–Br difference is small (about 0.7).", "3": "The H–Cl difference (about 0.9) is less than H–F."}'),
  ('CHE-6055', 'Chemical bonding', 'Ionic character of covalent bonds', 'moderate', 'PMDC MDCAT 2025 Chemistry 10.6; NUMS MDCAT 2026 Chemistry 10.6', 'A covalent bond between two different atoms has partial ionic character because', '["the electrons are completely transferred", "both atoms have the same electronegativity", "the bond contains a coordinate pair", "the shared electron pair is drawn closer to the more electronegative atom"]', 3, 'Unequal sharing gives the more electronegative atom a partial negative charge (δ−) and the other a partial positive charge (δ+), so the bond is partly ionic.', '{"0": "Complete transfer would make a purely ionic bond.", "1": "Equal electronegativities give a purely covalent, non-polar bond.", "2": "A coordinate bond can be non-polar or polar; it is not the cause."}'),
  ('CHE-6056', 'Chemical bonding', 'Ionic character of covalent bonds', 'moderate', 'PMDC MDCAT 2025 Chemistry 10.6; NUMS MDCAT 2026 Chemistry 10.6', 'A bond is usually taken to be about 50% ionic when the electronegativity difference between the two atoms is about', '["0.4", "1.0", "1.7", "3.3"]', 2, 'An electronegativity difference of about 1.7 corresponds to roughly 50% ionic character; larger differences give mainly ionic bonds.', '{"0": "Below about 0.4 a bond is considered almost non-polar.", "1": "A difference of 1.0 gives a polar covalent bond of about 20% ionic character.", "3": "3.3 exceeds the largest difference between any two elements."}'),
  ('CHE-6057', 'Organic chemistry', 'Naming alkenes', 'easy', 'PMDC MDCAT 2025 Chemistry 14.4–14.5; NUMS MDCAT 2026 Chemistry 14.5–14.6', 'The IUPAC name of CH₃–CH=CH–CH₃ is', '["but-1-ene", "but-2-ene", "butane", "2-butyne"]', 1, 'The chain has four carbons with the double bond starting at carbon 2, so it is but-2-ene.', '{"0": "In but-1-ene the double bond is between C1 and C2.", "2": "Butane has no double bond.", "3": "A \"-yne\" has a triple bond."}'),
  ('CHE-6058', 'Organic chemistry', 'Naming alkenes', 'moderate', 'PMDC MDCAT 2025 Chemistry 14.4–14.5; NUMS MDCAT 2026 Chemistry 14.5–14.6', 'The IUPAC name of CH₂=C(CH₃)–CH₃ is', '["2-methylprop-1-ene", "but-1-ene", "1-methylpropene", "but-2-ene"]', 0, 'The longest chain containing the double bond has three carbons (propene); a methyl group is on C2: 2-methylprop-1-ene (2-methylpropene).', '{"1": "But-1-ene is a straight four-carbon chain.", "2": "Numbering must give the double bond and substituent the lowest numbers; the methyl is on C2.", "3": "But-2-ene is CH₃CH=CHCH₃."}'),
  ('CHE-6059', 'Organic chemistry', 'Naming alkenes', 'hard', 'PMDC MDCAT 2025 Chemistry 14.4–14.5; NUMS MDCAT 2026 Chemistry 14.5–14.6', 'The IUPAC name of CH₂=CH–CH₂–CH(CH₃)–CH₃ is', '["2-methylpent-4-ene", "4-methylpent-2-ene", "2-methylpentene", "4-methylpent-1-ene"]', 3, 'Number from the end nearest the double bond: C1=C2–C3–C4(CH₃)–C5, so 4-methylpent-1-ene.', '{"0": "Numbering must give the double bond the lowest number.", "1": "The double bond starts at C1, not C2.", "2": "The position of the double bond must be shown."}'),
  ('CHE-6060', 'Organic chemistry', 'Structure of ethene', 'moderate', 'PMDC MDCAT 2025 Chemistry 14.4–14.5; NUMS MDCAT 2026 Chemistry 14.5–14.6', 'Which statement about the shape of the ethene molecule is correct?', '["The molecule is tetrahedral with bond angles of 109.5°.", "The molecule is linear with bond angles of 180°.", "All six atoms lie in one plane and the bond angles are about 120°.", "The two CH₂ groups lie in planes at right angles to each other."]', 2, 'Each carbon is sp² hybridised. The σ framework is trigonal planar (about 120°), and the unhybridised p orbitals overlap sideways above and below this plane to form the π bond, which keeps the molecule flat.', '{"0": "Tetrahedral (sp³) geometry is found in ethane.", "1": "Linear geometry is found in ethyne (sp).", "3": "The π overlap holds both CH₂ groups in the same plane."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-6061', 'Organic chemistry', 'Structure of ethene', 'moderate', 'PMDC MDCAT 2025 Chemistry 14.4–14.5; NUMS MDCAT 2026 Chemistry 14.5–14.6', 'There is no free rotation about the C=C bond in ethene because rotation would', '["break the σ bond", "destroy the sideways overlap of p orbitals that forms the π bond", "change the hybridisation to sp³", "make the molecule non-planar but leave all bonds intact"]', 1, 'The π bond exists only while the two p orbitals are parallel. Twisting one carbon would break this overlap, which needs a lot of energy; this is why alkenes show cis-trans (geometric) isomerism.', '{"0": "The σ bond is cylindrically symmetric and allows rotation, as in ethane.", "2": "Rotation by itself does not rehybridise the carbons.", "3": "Rotation would break the π bond, so not all bonds stay intact."}'),
  ('CHE-6062', 'Organic chemistry', 'Structure of ethene', 'moderate', 'PMDC MDCAT 2025 Chemistry 14.4–14.5; NUMS MDCAT 2026 Chemistry 14.5–14.6', 'Compared with the C–C bond in ethane (154 pm, 348 kJ mol⁻¹), the C=C bond in ethene (134 pm, 614 kJ mol⁻¹) is', '["shorter and stronger, but less than twice as strong", "longer and weaker", "shorter and exactly twice as strong", "the same length but stronger"]', 0, 'The extra π bond pulls the carbons closer and adds strength, but a π bond (sideways overlap) is weaker than a σ bond, so 614 kJ mol⁻¹ is less than 2 × 348 = 696 kJ mol⁻¹.', '{"1": "A double bond is shorter and stronger than a single bond.", "2": "614 is less than 696, so it is not twice as strong.", "3": "The double bond is 20 pm shorter."}'),
  ('CHE-6063', 'Organic chemistry', 'Sulphonation of benzene', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.13; NUMS MDCAT 2026 Chemistry 14.16', 'Benzene is converted into benzenesulphonic acid by heating it with', '["concentrated HNO₃ and concentrated H₂SO₄", "dilute H₂SO₄", "SO₂ and water", "fuming sulphuric acid (H₂SO₄ containing dissolved SO₃)"]', 3, 'C₆H₆ + H₂SO₄ (SO₃) → C₆H₅SO₃H + H₂O. Fuming sulphuric acid (oleum) reacts readily; concentrated acid needs prolonged heating.', '{"0": "This nitrating mixture gives nitrobenzene.", "1": "Dilute acid does not sulphonate benzene; it can reverse sulphonation.", "2": "SO₂ does not sulphonate benzene."}'),
  ('CHE-6064', 'Organic chemistry', 'Sulphonation of benzene', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.13; NUMS MDCAT 2026 Chemistry 14.16', 'In the sulphonation of benzene, the electrophile that attacks the ring is', '["NO₂⁺", "HSO₄⁻", "SO₃ (or HSO₃⁺)", "H₃O⁺"]', 2, 'SO₃ is electron-deficient at sulphur (S carries a large δ+), so it acts as the electrophile; in strong acid it may be present as HSO₃⁺.', '{"0": "NO₂⁺ is the electrophile in nitration.", "1": "HSO₄⁻ is an anion and not an electrophile.", "3": "H₃O⁺ is not the substituting electrophile."}'),
  ('CHE-6065', 'Organic chemistry', 'Sulphonation of benzene', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.13; NUMS MDCAT 2026 Chemistry 14.16', 'Which feature makes sulphonation different from the nitration and halogenation of benzene?', '["It needs a Lewis acid catalyst such as FeCl₃.", "It is reversible: heating benzenesulphonic acid with dilute acid or steam gives back benzene.", "It is an addition reaction.", "It gives cyclohexane."]', 1, 'Sulphonation is reversible. Removing the –SO₃H group by heating with steam/dilute acid (desulphonation) lets chemists use it as a temporary blocking group.', '{"0": "A Lewis acid is needed for halogenation and Friedel-Crafts reactions, not sulphonation.", "2": "Sulphonation is a substitution; the aromatic ring is kept.", "3": "Hydrogenation, not sulphonation, gives cyclohexane."}'),
  ('CHE-6066', 'Organic chemistry', 'Sulphonation of benzene', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.13; NUMS MDCAT 2026 Chemistry 14.16', 'Sulphonation of methylbenzene (toluene) gives mainly', '["o- and p-toluenesulphonic acids", "m-toluenesulphonic acid", "benzoic acid", "benzenesulphonic acid and methane"]', 0, 'The methyl group is an electron-donating ortho/para director, so the –SO₃H group enters mainly at the 2- and 4-positions (p-isomer favoured at higher temperature).', '{"1": "Meta products come from deactivating groups such as –NO₂.", "2": "Benzoic acid comes from side-chain oxidation with KMnO₄.", "3": "The methyl group is not removed."}'),
  ('CHE-6067', 'Organic chemistry', 'Friedel-Crafts reactions', 'moderate', 'PMDC MDCAT 2025 Chemistry 14.13; NUMS MDCAT 2026 Chemistry 14.16', 'In the Friedel-Crafts methylation of benzene with CH₃Cl, the role of anhydrous AlCl₃ is to', '["act as a reducing agent", "add chlorine to the ring", "absorb the water formed in the reaction", "act as a Lewis acid that pulls Cl⁻ away and produces the CH₃⁺ electrophile"]', 3, 'CH₃Cl + AlCl₃ → CH₃⁺ + AlCl₄⁻. The carbocation attacks the ring; AlCl₄⁻ then removes H⁺, giving toluene, HCl and regenerated AlCl₃.', '{"0": "AlCl₃ is not a reducing agent.", "1": "No chlorine is added to the ring in alkylation.", "2": "No water is formed; anhydrous conditions are needed because water destroys AlCl₃."}'),
  ('CHE-6068', 'Organic chemistry', 'Friedel-Crafts reactions', 'moderate', 'PMDC MDCAT 2025 Chemistry 14.13; NUMS MDCAT 2026 Chemistry 14.16', 'Benzene reacts with ethanoyl chloride (CH₃COCl) in the presence of anhydrous AlCl₃ to give', '["toluene", "benzoic acid", "phenylethanone (acetophenone)", "ethylbenzene"]', 2, 'This is Friedel-Crafts acylation: the acylium ion CH₃CO⁺ substitutes into the ring, giving C₆H₅COCH₃.', '{"0": "Toluene comes from methylation with CH₃Cl.", "1": "Benzoic acid is not formed in this reaction.", "3": "Ethylbenzene comes from alkylation with C₂H₅Cl."}'),
  ('CHE-6069', 'Organic chemistry', 'Friedel-Crafts reactions', 'hard', 'PMDC MDCAT 2025 Chemistry 14.13; NUMS MDCAT 2026 Chemistry 14.16', 'Friedel-Crafts alkylation of benzene often gives polyalkylated products, but acylation stops after one substitution. This is because', '["acyl chlorides are less reactive than benzene", "an alkyl group activates the ring, while an acyl group deactivates it", "AlCl₃ is used up in alkylation", "alkylation is an addition reaction"]', 1, 'The electron-donating alkyl group makes the product more reactive than benzene, so it reacts again. The electron-withdrawing C=O of an acyl group makes the product less reactive, so further substitution is slow.', '{"0": "Acyl chlorides are readily converted to acylium ions.", "2": "AlCl₃ is regenerated in alkylation.", "3": "Both are electrophilic substitutions."}'),
  ('CHE-6070', 'Organic chemistry', 'Naming alkynes', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'The IUPAC name of CH₃–C≡C–CH₃ is', '["but-2-yne", "but-1-yne", "but-2-ene", "butyne-2"]', 0, 'Four-carbon chain with the triple bond starting at C2: but-2-yne (2-butyne).', '{"1": "In but-1-yne the triple bond is at the end of the chain.", "2": "\"-ene\" indicates a double bond.", "3": "The locant goes before the \"-yne\" suffix, not after it."}'),
  ('CHE-6071', 'Organic chemistry', 'Naming alkynes', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'The IUPAC name of HC≡C–CH(CH₃)–CH₃ is', '["2-methylbut-3-yne", "3-methylbutyne-2", "isopentyne", "3-methylbut-1-yne"]', 3, 'Number from the triple-bond end: C1≡C2–C3(CH₃)–C4, giving 3-methylbut-1-yne.', '{"0": "The triple bond must get the lowest locant.", "1": "The triple bond is between C1 and C2.", "2": "This is not an IUPAC name."}'),
  ('CHE-6072', 'Organic chemistry', 'Alkynes', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'Alkynes have the general formula', '["CₙH₂ₙ₊₂", "CₙH₂ₙ", "CₙH₂ₙ₋₂", "CₙHₙ"]', 2, 'A C≡C triple bond removes four hydrogens compared with the alkane, so open-chain alkynes are CₙH₂ₙ₋₂ (e.g. ethyne C₂H₂, propyne C₃H₄).', '{"0": "This is the formula of alkanes.", "1": "This is the formula of alkenes and cycloalkanes.", "3": "This fits benzene (C₆H₆) and ethyne but not alkynes in general."}'),
  ('CHE-6073', 'Organic chemistry', 'Preparation of alkynes', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'Ethyne can be prepared from 1,2-dibromoethane by', '["warming with aqueous KOH", "heating with excess alcoholic KOH (or NaNH₂), which removes two molecules of HBr", "heating with zinc dust", "treating with hydrogen and nickel"]', 1, 'Two successive dehydrohalogenations (E2 eliminations): BrCH₂CH₂Br → CH₂=CHBr → HC≡CH. A strong base such as NaNH₂ is needed for the second step.', '{"0": "Aqueous KOH mainly substitutes, giving ethane-1,2-diol.", "2": "Zinc removes both Br atoms from a vicinal dibromide to give ethene, not ethyne.", "3": "H₂/Ni does not remove halogens to form a triple bond."}'),
  ('CHE-6074', 'Organic chemistry', 'Preparation of alkynes', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'Which compound gives propyne when heated with excess alcoholic KOH (followed by NaNH₂)?', '["1,2-dibromopropane", "1-bromopropane", "2-bromopropane", "propan-1-ol"]', 0, 'A vicinal (or geminal) dihalide loses two molecules of HBr to form a triple bond: CH₃CHBrCH₂Br → CH₃C≡CH.', '{"1": "A monohalide loses only one HBr, giving propene.", "2": "2-Bromopropane gives propene.", "3": "An alcohol needs an acid catalyst and dehydrates to propene, not propyne."}'),
  ('CHE-6075', 'Organic chemistry', 'Preparation of alkynes', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'Ethyne is conveniently made in the laboratory by adding water to', '["calcium carbonate", "calcium oxide", "aluminium carbide", "calcium carbide"]', 3, 'CaC₂ + 2H₂O → C₂H₂ + Ca(OH)₂. The carbide ion C₂²⁻ is the conjugate base of ethyne.', '{"0": "CaCO₃ with acid gives CO₂.", "1": "CaO with water gives Ca(OH)₂ only.", "2": "Al₄C₃ with water gives methane."}'),
  ('CHE-6076', 'Organic chemistry', 'Acidity of alkynes', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'The hydrogen attached to a triply bonded carbon (as in ethyne) is weakly acidic because', '["the C–H bond in ethyne is very long", "ethyne contains an –OH group", "the sp-hybridised carbon has 50% s character and holds electrons closely, stabilising the carbanion", "the triple bond donates electrons to hydrogen"]', 2, 'Greater s character means the electrons are held nearer the nucleus, so sp carbon is more electronegative than sp² or sp³ carbon. The acetylide ion formed when H⁺ is lost is relatively stable.', '{"0": "The ≡C–H bond is actually the shortest C–H bond.", "1": "Ethyne contains only C and H.", "3": "Donating electrons to hydrogen would make it less acidic."}'),
  ('CHE-6077', 'Organic chemistry', 'Acidity of alkynes', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'Which compound reacts with sodamide (NaNH₂) to form a sodium salt?', '["But-2-yne", "Propyne", "Ethene", "Ethane"]', 1, 'Only terminal alkynes (with ≡C–H) are acidic enough: CH₃C≡CH + NaNH₂ → CH₃C≡C⁻Na⁺ + NH₃.', '{"0": "But-2-yne has no hydrogen on a triply bonded carbon.", "2": "Ethene (sp² C–H) is far too weakly acidic.", "3": "Ethane is even less acidic."}'),
  ('CHE-6078', 'Organic chemistry', 'Acidity of alkynes', 'hard', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'Which reagent distinguishes but-1-yne from but-2-yne?', '["Ammoniacal silver nitrate", "Bromine water", "Hydrogen with nickel", "Alkaline KMnO₄"]', 0, 'But-1-yne is a terminal alkyne and forms a white precipitate of silver butynide with ammoniacal AgNO₃; but-2-yne has no acidic hydrogen and does not react.', '{"1": "Both decolourise bromine water.", "2": "Both are hydrogenated to butane.", "3": "Both are oxidised and decolourise KMnO₄."}'),
  ('CHE-6079', 'Organic chemistry', 'Acidity of alkynes', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'The correct order of acidic strength of the hydrocarbons is', '["ethane > ethene > ethyne", "ethene > ethyne > ethane", "all three are equally acidic", "ethyne > ethene > ethane"]', 3, 'Acidity follows the s character of the carbon bearing the hydrogen: sp (50%) > sp² (33%) > sp³ (25%).', '{"0": "This is the reverse order.", "1": "Ethyne, not ethene, is the most acidic.", "2": "Their acidities differ by many powers of ten."}'),
  ('CHE-6080', 'Organic chemistry', 'Reactions of alkynes', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'But-2-yne is hydrogenated with Lindlar''s catalyst (Pd poisoned with BaSO₄ or CaCO₃ and quinoline). The main product is', '["butane", "trans-but-2-ene", "cis-but-2-ene", "but-1-ene"]', 2, 'The poisoned catalyst stops at the alkene stage, and both hydrogens add to the same face of the triple bond (syn addition), giving the cis alkene.', '{"0": "Butane forms with an active catalyst such as Ni or Pt and excess H₂.", "1": "Trans alkenes come from reduction with sodium in liquid ammonia.", "3": "The position of the multiple bond does not change."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-6081', 'Organic chemistry', 'Reactions of alkynes', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'Ethyne reacts with excess hydrogen over a nickel catalyst at about 200–300 °C to give', '["ethene only", "ethane", "benzene", "ethanol"]', 1, 'With an active catalyst and excess H₂, two molecules of H₂ add: HC≡CH + 2H₂ → CH₃CH₃.', '{"0": "Ethene is only an intermediate under these conditions.", "2": "Benzene forms when ethyne is passed through a red-hot iron tube (trimerisation).", "3": "No oxygen is present to form ethanol."}'),
  ('CHE-6082', 'Organic chemistry', 'Reactions of alkynes', 'hard', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'Propyne reacts with two moles of HBr. The main product is', '["2,2-dibromopropane", "1,1-dibromopropane", "1,2-dibromopropane", "1,3-dibromopropane"]', 0, 'Both additions follow Markovnikov''s rule: H goes to the terminal carbon and Br to C2, first giving 2-bromopropene and then 2,2-dibromopropane (a geminal dihalide).', '{"1": "This is anti-Markovnikov addition.", "2": "1,2-Dibromopropane would come from adding Br₂ to propene.", "3": "Addition cannot put Br on C3, which has no multiple bond."}'),
  ('CHE-6083', 'Organic chemistry', 'Reactions of alkynes', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'When ethyne is passed into dilute H₂SO₄ containing HgSO₄ at about 75 °C, the first product, which immediately rearranges to ethanal, is', '["ethanol", "ethylene glycol", "acetic acid", "vinyl alcohol (ethenol)"]', 3, 'Water adds across the triple bond to give the enol CH₂=CHOH, which tautomerises to the more stable aldehyde CH₃CHO.', '{"0": "Ethanol is not formed in this reaction.", "1": "Ethane-1,2-diol forms from oxidising ethene, not hydrating ethyne.", "2": "Ethanoic acid is formed only if ethanal is oxidised further."}'),
  ('CHE-6084', 'Organic chemistry', 'Reactivity of alkynes', 'hard', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 14.15–14.18; NUMS MDCAT 2026 Chemistry 14.18–14.22', 'Which comparison of the reactivity of hydrocarbons is generally correct?', '["Alkanes are more reactive than alkynes towards bromine.", "Benzene reacts with bromine water faster than ethene.", "Alkynes undergo addition but are generally slightly less reactive than alkenes towards electrophiles; benzene usually prefers substitution to addition.", "Alkynes do not undergo addition reactions."]', 2, 'The π electrons of an alkyne are held more tightly by the sp carbons, and the vinyl carbocation is less stable, so electrophilic addition is usually slower than for alkenes. Benzene keeps its stable delocalised ring by substituting.', '{"0": "Alkanes react with bromine only by free-radical substitution in UV light.", "1": "Benzene does not decolourise bromine water; ethene does so rapidly.", "3": "Alkynes add H₂, X₂, HX and H₂O."}'),
  ('CHE-6085', 'Alkyl halides', 'Naming alkyl halides', 'easy', 'PMDC MDCAT 2025 Chemistry 15.1; NUMS MDCAT 2026 Chemistry 15.1', 'The IUPAC name of CH₃CH₂CH(Br)CH₃ is', '["1-bromobutane", "2-bromobutane", "3-bromobutane", "sec-butyl bromide"]', 1, 'Numbering from the end nearer the bromine puts Br on C2: 2-bromobutane.', '{"0": "In 1-bromobutane Br is on the end carbon.", "2": "Numbering must give the substituent the lowest locant.", "3": "This is a common name, not the IUPAC name."}'),
  ('CHE-6086', 'Alkyl halides', 'Naming alkyl halides', 'moderate', 'PMDC MDCAT 2025 Chemistry 15.1; NUMS MDCAT 2026 Chemistry 15.1', '(CH₃)₃C–Cl is named and classified as', '["2-chloro-2-methylpropane, a tertiary alkyl halide", "1-chlorobutane, a primary alkyl halide", "2-chlorobutane, a secondary alkyl halide", "1-chloro-2-methylpropane, a primary alkyl halide"]', 0, 'The longest chain through C–Cl is propane, with Cl and CH₃ both on C2. The carbon bearing Cl is attached to three other carbons, so it is tertiary.', '{"1": "There is no straight four-carbon chain.", "2": "The C–Cl carbon is bonded to three carbons, not two.", "3": "This is (CH₃)₂CHCH₂Cl, a different isomer."}'),
  ('CHE-6087', 'Alkyl halides', 'Naming alkyl halides', 'hard', 'PMDC MDCAT 2025 Chemistry 15.1; NUMS MDCAT 2026 Chemistry 15.1', 'The IUPAC name of BrCH₂CH₂CH(Cl)CH₃ is', '["4-bromo-2-chlorobutane", "3-chloro-1-bromobutane", "1-chloro-3-bromobutane", "1-bromo-3-chlorobutane"]', 3, 'Number to give the lowest set of locants: {1,3} beats {2,4}. Substituents are then listed alphabetically (bromo before chloro): 1-bromo-3-chlorobutane.', '{"0": "The locant set {2,4} is higher than {1,3}.", "1": "Substituent prefixes must be written in alphabetical order.", "2": "Cl is on C3, not C1."}'),
  ('CHE-6088', 'Aldehydes, ketones and carboxylic acids', 'Naming aldehydes and ketones', 'easy', 'PMDC MDCAT 2025 Chemistry 17.1, 18.1; NUMS MDCAT 2026 Chemistry 17.1, 18.1', 'The IUPAC name of CH₃CH₂COCH₃ is', '["butanal", "propanone", "butan-2-one", "butan-2-ol"]', 2, 'Four carbons with a C=O inside the chain at C2 make a ketone: butan-2-one (butanone).', '{"0": "Butanal is an aldehyde, CH₃CH₂CH₂CHO.", "1": "Propanone has three carbons.", "3": "\"-ol\" means an alcohol."}'),
  ('CHE-6089', 'Aldehydes, ketones and carboxylic acids', 'Naming aldehydes and ketones', 'moderate', 'PMDC MDCAT 2025 Chemistry 17.1, 18.1; NUMS MDCAT 2026 Chemistry 17.1, 18.1', 'The IUPAC name of (CH₃)₂CHCHO is', '["butanal", "2-methylpropanal", "2-methylpropanone", "isobutanol"]', 1, 'The CHO carbon is C1 of a three-carbon chain with a methyl on C2: 2-methylpropanal.', '{"0": "Butanal is the straight-chain isomer.", "2": "A ketone cannot have its C=O at the end of the chain.", "3": "This is an alcohol name."}'),
  ('CHE-6090', 'Aldehydes, ketones and carboxylic acids', 'Naming carboxylic acids', 'moderate', 'PMDC MDCAT 2025 Chemistry 17.1, 18.1; NUMS MDCAT 2026 Chemistry 17.1, 18.1', 'The IUPAC name of CH₃CH(Cl)COOH is', '["2-chloropropanoic acid", "3-chloropropanoic acid", "2-chloroethanoic acid", "α-chlorobutyric acid"]', 0, 'The COOH carbon is C1; the chain has three carbons with Cl on C2: 2-chloropropanoic acid.', '{"1": "In 3-chloropropanoic acid Cl is on the CH₂ at the far end.", "2": "The chain has three carbons, not two.", "3": "This is not an IUPAC name and has the wrong chain length."}'),
  ('CHE-6091', 'Aldehydes, ketones and carboxylic acids', 'Preparation of carboxylic acids', 'moderate', 'PMDC MDCAT 2025 Chemistry 17.1, 18.1; NUMS MDCAT 2026 Chemistry 17.1, 18.1', 'Ethanoic acid can be prepared by acid hydrolysis of', '["methanenitrile (HCN)", "propanenitrile (C₂H₅CN)", "ethanamide reduction", "ethanenitrile (CH₃CN)"]', 3, 'CH₃CN + 2H₂O + H⁺ → CH₃COOH + NH₄⁺. The nitrile carbon becomes the COOH carbon, so the acid has the same number of carbons as the nitrile.', '{"0": "HCN hydrolyses to methanoic acid.", "1": "Propanenitrile gives propanoic acid.", "2": "Reducing an amide gives an amine, not an acid."}'),
  ('CHE-6092', 'Aldehydes, ketones and carboxylic acids', 'Preparation of carboxylic acids', 'hard', 'PMDC MDCAT 2025 Chemistry 17.1, 18.1; NUMS MDCAT 2026 Chemistry 17.1, 18.1', 'CH₃MgBr is treated with dry CO₂ and the product is hydrolysed with dilute acid. The final product is', '["methanol", "methanoic acid", "ethanoic acid", "propanone"]', 2, 'The Grignard reagent adds to CO₂ to give CH₃COOMgBr, which acid hydrolysis converts to CH₃COOH. One carbon is added to the chain.', '{"0": "Methanol would need methanal and reduction, not CO₂.", "1": "Methanoic acid has one carbon; CO₂ adds a second carbon here.", "3": "Propanone is not formed from CO₂."}'),
  ('CHE-6093', 'Macromolecules', 'Proteins in nutrition', 'easy', 'PMDC MDCAT 2025 Chemistry 19.2; NUMS MDCAT 2026 Chemistry 19.2', 'Essential amino acids are those that', '["are found only in plant proteins", "cannot be made by the human body and must be obtained from the diet", "are needed only by children", "contain sulphur"]', 1, 'The body can synthesise some amino acids from others, but about nine (e.g. lysine, leucine, valine) cannot be made and must come from food proteins.', '{"0": "Essential amino acids occur in both animal and plant proteins.", "2": "Adults need them too.", "3": "Only a few amino acids (cysteine, methionine) contain sulphur."}'),
  ('CHE-6094', 'Macromolecules', 'Proteins in nutrition', 'easy', 'PMDC MDCAT 2025 Chemistry 19.2; NUMS MDCAT 2026 Chemistry 19.2', 'Kwashiorkor, seen in young children with swollen bellies and poor growth, is caused mainly by a diet deficient in', '["protein", "vitamin C", "iodine", "iron"]', 0, 'Kwashiorkor results from severe protein deficiency even when some energy is supplied (often after weaning onto starchy foods).', '{"1": "Vitamin C deficiency causes scurvy.", "2": "Iodine deficiency causes goitre.", "3": "Iron deficiency causes anaemia."}'),
  ('CHE-6095', 'Macromolecules', 'Functions of proteins', 'easy', 'PMDC MDCAT 2025 Chemistry 19.2; NUMS MDCAT 2026 Chemistry 19.2', 'Which protein has a mainly structural role in the body?', '["Haemoglobin", "Insulin", "Amylase", "Collagen"]', 3, 'Collagen is a fibrous protein that gives strength to skin, tendons, cartilage and bone.', '{"0": "Haemoglobin is a transport protein (oxygen).", "1": "Insulin is a hormone.", "2": "Amylase is an enzyme."}'),
  ('CHE-6096', 'Industrial chemistry', 'Adhesives', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 20.1', 'Which of these is a synthetic adhesive?', '["Starch paste", "Animal glue (from gelatin)", "Epoxy resin", "Casein glue"]', 2, 'Epoxy resins are man-made polymers. Starch paste, animal glue and casein (from milk) are natural adhesives.', '{"0": "Starch is a natural polymer from plants.", "1": "Animal glue is made from collagen/gelatin, a natural protein.", "3": "Casein is a natural milk protein."}'),
  ('CHE-6097', 'Industrial chemistry', 'Adhesives', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 20.1', '"Superglue", which sets within seconds on contact with traces of moisture, is based on', '["polyvinyl acetate", "cyanoacrylates", "urea-formaldehyde", "natural rubber"]', 1, 'Alkyl 2-cyanoacrylates polymerise rapidly when triggered by the small amount of water on most surfaces, forming strong bonds.', '{"0": "PVA (white glue) sets slowly as water evaporates.", "2": "Urea-formaldehyde resins are thermosetting wood adhesives that need curing.", "3": "Rubber-based adhesives set as solvent evaporates."}'),
  ('CHE-6098', 'Industrial chemistry', 'Adhesives', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 20.1', 'A two-part epoxy adhesive hardens after the resin and hardener are mixed because', '["the two parts react to form a cross-linked, thermosetting polymer", "the solvent evaporates", "the mixture cools and crystallises", "air oxidises the resin"]', 0, 'The hardener (often an amine) reacts with the epoxide groups, building a three-dimensional network. Such thermosetting adhesives cannot be softened again by heating.', '{"1": "Epoxies are typically solvent-free; setting is chemical.", "2": "Hardening is a chemical reaction, not crystallisation.", "3": "Curing does not depend on oxygen from the air."}'),
  ('CHE-6099', 'Industrial chemistry', 'Adhesives', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 20.1', 'The white, water-based glue commonly used for wood, paper and cardboard is', '["polystyrene", "PVC", "Teflon", "polyvinyl acetate (PVA)"]', 3, 'PVA is dispersed in water; it sets as the water is absorbed or evaporates, leaving a flexible polymer film.', '{"0": "Polystyrene is used for packaging and disposable cups.", "1": "PVC is used for pipes and cable insulation.", "2": "Teflon is a non-stick polymer, not an adhesive."}'),
  ('CHE-6100', 'Industrial chemistry', 'Dyes', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 20.2', 'Which statement best distinguishes a dye from a pigment?', '["A dye is always natural; a pigment is always synthetic.", "A dye is always inorganic.", "A dye is soluble in the medium and becomes attached to the material; a pigment is insoluble and is held in a binder.", "Pigments are used only in food."]', 2, 'Dyes dissolve (in water or another medium) and bind to fibres; pigments are insoluble particles held on the surface by a binder, as in paints.', '{"0": "Both dyes and pigments can be natural or synthetic.", "1": "Most dyes are organic compounds.", "3": "Pigments are used mainly in paints, inks and plastics."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-6101', 'Industrial chemistry', 'Dyes', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 20.2', 'Indigo is insoluble in water. It is applied to cotton by reducing it to a soluble colourless form, dipping the cloth, and letting air oxidise it back on the fibre. This makes indigo a', '["direct dye", "vat dye", "mordant dye", "disperse dye"]', 1, 'Vat dyes (e.g. indigo) are reduced in a vat to a soluble "leuco" form, absorbed by the fibre and then re-oxidised to the insoluble coloured dye, giving good fastness.', '{"0": "Direct dyes dissolve in water and dye cotton without any chemical step.", "2": "Mordant dyes need a metal salt to fix them to the fibre.", "3": "Disperse dyes are used as fine dispersions for polyester."}'),
  ('CHE-6102', 'Industrial chemistry', 'Dyes', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 20.2', 'In mordant dyeing, for example with alizarin, the mordant is', '["a metal salt (such as an aluminium or chromium salt) that binds the dye to the fibre", "an acid that dissolves the dye", "a reducing agent", "a detergent that cleans the fibre"]', 0, 'The metal ion forms a complex (a "lake") with the dye and the fibre, fixing a dye that would otherwise wash out; different metals give different shades.', '{"1": "Mordants fix dyes; they do not just dissolve them.", "2": "A reducing agent is used for vat dyes.", "3": "Detergents only clean the fibre before dyeing."}'),
  ('CHE-6103', 'Industrial chemistry', 'Dyes', 'moderate', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 20.2', 'In a dye molecule, groups such as –OH or –NH₂ attached to the coloured part are called auxochromes. Their role is to', '["make the dye insoluble", "remove the colour", "act as the main source of colour", "deepen the colour and help the dye bind to the fibre"]', 3, 'The chromophore (e.g. –N=N– in azo dyes) is the source of colour; auxochromes intensify or shift the colour and give the dye affinity for the fibre.', '{"0": "Auxochromes such as –OH, –NH₂ and –SO₃H usually increase solubility or binding.", "1": "They intensify rather than remove colour.", "2": "The chromophore, not the auxochrome, is the main colour-bearing group."}'),
  ('CHE-6104', 'Industrial chemistry', 'Dyes', 'easy', 'Standard topic not in the PECTAA Chemistry books; PMDC MDCAT 2025 Chemistry 20.2', 'Besides colouring textiles, dyes such as methylene blue and crystal violet are widely used', '["as fuels", "as fertilisers", "as stains for cells and bacteria in biology laboratories", "as refrigerants"]', 2, 'Biological stains colour cell parts so they can be seen under the microscope; crystal violet is used in the Gram stain.', '{"0": "Dyes are not used as fuels.", "1": "They are not fertilisers.", "3": "They are not refrigerants."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Physics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PHY-6001', 'Force and motion', 'Displacement-time graph', 'easy', 'PMDC MDCAT 2025 Physics 2.1–2.5; NUMS MDCAT 2026 Physics 1.1–1.5', 'The slope of a displacement-time graph of an object moving along a straight line gives its', '["acceleration", "velocity", "displacement", "force"]', 1, 'Slope = Δs/Δt, which is velocity. A steeper line means a greater velocity.', '{"0": "Acceleration is the slope of a velocity-time graph.", "2": "Displacement is read directly from the graph, not from its slope.", "3": "Force cannot be read from a displacement-time graph alone."}'),
  ('PHY-6002', 'Force and motion', 'Displacement-time graph', 'easy', 'PMDC MDCAT 2025 Physics 2.1–2.5; NUMS MDCAT 2026 Physics 1.1–1.5', 'The displacement-time graph of a body is a straight line parallel to the time axis. The body is', '["at rest", "moving with uniform velocity", "moving with uniform acceleration", "moving with decreasing velocity"]', 0, 'The displacement does not change with time, so the slope (velocity) is zero: the body is at rest.', '{"1": "Uniform velocity gives a sloping straight line.", "2": "Uniform acceleration gives a curve (parabola).", "3": "Decreasing velocity gives a curve whose slope gets smaller."}'),
  ('PHY-6003', 'Force and motion', 'Displacement-time graph', 'moderate', 'PMDC MDCAT 2025 Physics 2.1–2.5; NUMS MDCAT 2026 Physics 1.1–1.5', 'The displacement-time graph of a body is a curve that gets steeper as time passes. This shows that the body is', '["at rest", "moving with constant velocity", "slowing down", "speeding up (accelerating)"]', 3, 'The slope of the graph is the velocity; an increasing slope means the velocity is increasing.', '{"0": "A body at rest has a horizontal graph.", "1": "Constant velocity gives a straight line of constant slope.", "2": "Slowing down would make the curve less steep with time."}'),
  ('PHY-6004', 'Force and motion', 'Displacement-time graph', 'hard', 'PMDC MDCAT 2025 Physics 2.1–2.5; NUMS MDCAT 2026 Physics 1.1–1.5', 'The displacement-time graphs of two cars moving along the same straight road are straight lines making angles of 30° and 60° with the time axis. The ratio of their velocities v₁ : v₂ is', '["1 : 2", "1 : √3", "1 : 3", "2 : 1"]', 2, 'Velocity = slope = tan θ, so v₁/v₂ = tan 30°/tan 60° = (1/√3)/√3 = 1/3.', '{"0": "This compares the angles, not their tangents.", "1": "This uses only one factor of √3.", "3": "This inverts the angle ratio."}'),
  ('PHY-6005', 'Force and motion', 'Uniform and variable acceleration', 'easy', 'PMDC MDCAT 2025 Physics 2.1–2.5; NUMS MDCAT 2026 Physics 1.1–1.5', 'A body has uniform acceleration when', '["its velocity is constant", "its velocity changes by equal amounts in equal intervals of time", "it covers equal distances in equal intervals of time", "its acceleration changes at a steady rate"]', 1, 'Uniform acceleration means the rate of change of velocity is constant, so equal velocity changes occur in equal times; the velocity-time graph is a straight line.', '{"0": "Constant velocity means zero acceleration.", "2": "Equal distances in equal times means uniform velocity.", "3": "A changing acceleration is variable acceleration."}'),
  ('PHY-6006', 'Force and motion', 'Uniform and variable acceleration', 'moderate', 'PMDC MDCAT 2025 Physics 2.1–2.5; NUMS MDCAT 2026 Physics 1.1–1.5', 'The velocity-time graph of a body is a curve. Its acceleration at a particular instant is found from the', '["slope of the tangent to the curve at that instant", "area under the curve up to that instant", "value of velocity at that instant divided by 2", "length of the curve"]', 0, 'For variable acceleration the instantaneous acceleration is the gradient of the tangent at that point on the v-t graph.', '{"1": "The area under a v-t graph gives displacement.", "2": "This has no physical meaning.", "3": "The length of the curve has no physical meaning here."}'),
  ('PHY-6007', 'Force and motion', 'Velocity-time graph', 'moderate', 'PMDC MDCAT 2025 Physics 2.4–2.5; NUMS MDCAT 2026 Physics 1.4–1.5 (velocity-time graph)', 'A car starts from rest and accelerates uniformly to 20 m s⁻¹ in 10 s. Using the area under its velocity-time graph, the distance covered is', '["200 m", "50 m", "400 m", "100 m"]', 3, 'The v-t graph is a triangle: area = ½ × 10 s × 20 m s⁻¹ = 100 m.', '{"0": "This uses the rectangle 10 × 20 and forgets the factor ½.", "1": "This halves the correct answer again.", "2": "This doubles instead of halving."}'),
  ('PHY-6008', 'Force and motion', 'Projectile motion', 'moderate', 'PMDC MDCAT 2025 Physics 2.6–2.11; NUMS MDCAT 2026 Physics 1.6–1.11', 'A ball is thrown at 20 m s⁻¹ at 30° above the horizontal. Ignoring air resistance (g = 10 m s⁻²), its maximum height is', '["10 m", "15 m", "5 m", "20 m"]', 2, 'H = v²sin²θ/2g = (400 × 0.25)/20 = 5 m.', '{"0": "This uses sin θ instead of sin²θ.", "1": "This uses sin²60°.", "3": "This is v²/2g, the height for a vertical throw."}'),
  ('PHY-6009', 'Force and motion', 'Projectile motion', 'moderate', 'PMDC MDCAT 2025 Physics 2.6–2.11; NUMS MDCAT 2026 Physics 1.6–1.11', 'For the same ball (20 m s⁻¹ at 30°, g = 10 m s⁻²), the time of flight is', '["1 s", "2 s", "3.5 s", "4 s"]', 1, 'T = 2v sin θ/g = (2 × 20 × 0.5)/10 = 2 s.', '{"0": "This is only the time to reach the highest point.", "2": "This uses cos 30° instead of sin 30°.", "3": "This is the time of flight for a vertical throw."}'),
  ('PHY-6010', 'Force and motion', 'Projectile motion', 'easy', 'PMDC MDCAT 2025 Physics 2.6–2.11; NUMS MDCAT 2026 Physics 1.6–1.11', 'At the highest point of its path, a projectile (no air resistance) has', '["only a horizontal velocity, and acceleration g downward", "zero velocity and zero acceleration", "zero velocity and acceleration g downward", "only a vertical velocity"]', 0, 'The vertical velocity is zero at the top, but the horizontal component v cos θ is unchanged throughout; the acceleration is always g downward.', '{"1": "The acceleration is never zero during free flight.", "2": "The horizontal velocity is not zero unless it was thrown straight up.", "3": "The vertical velocity is the part that becomes zero."}'),
  ('PHY-6011', 'Force and motion', 'Projectile motion', 'hard', 'PMDC MDCAT 2025 Physics 2.6–2.11; NUMS MDCAT 2026 Physics 1.6–1.11', 'A projectile launched at 45° has horizontal range R. Its maximum height is', '["R", "R/2", "2R", "R/4"]', 3, 'At 45°, R = v²/g and H = v²sin²45°/2g = v²/4g, so H = R/4.', '{"0": "H equals R only for an angle of about 76°.", "1": "This forgets the factor sin²45° = ½ in H.", "2": "The height is less than the range at 45°."}'),
  ('PHY-6012', 'Force and motion', 'Conservation of momentum', 'moderate', 'PMDC MDCAT 2025 Physics 2.14–2.17; NUMS MDCAT 2026 Physics 1.14–1.17', 'A 4 kg gun fires a 20 g bullet with a speed of 400 m s⁻¹. The recoil speed of the gun is', '["1 m s⁻¹", "4 m s⁻¹", "2 m s⁻¹", "8 m s⁻¹"]', 2, 'Total momentum is zero before and after: 0.020 × 400 = 4 × v, so v = 8/4 = 2 m s⁻¹ in the opposite direction.', '{"0": "This halves the correct value.", "1": "This uses a bullet mass of 40 g.", "3": "This is the bullet''s momentum, not the gun''s speed."}'),
  ('PHY-6013', 'Force and motion', 'Conservation of momentum', 'moderate', 'PMDC MDCAT 2025 Physics 2.14–2.17; NUMS MDCAT 2026 Physics 1.14–1.17', 'A body at rest explodes into two pieces of masses 1 kg and 2 kg. The 1 kg piece moves off at 6 m s⁻¹. The 2 kg piece moves', '["at 6 m s⁻¹ in the same direction", "at 3 m s⁻¹ in the opposite direction", "at 12 m s⁻¹ in the opposite direction", "at 3 m s⁻¹ in the same direction"]', 1, 'Momentum before is zero, so 1 × 6 = 2 × v: v = 3 m s⁻¹, and the pieces move in opposite directions.', '{"0": "The total momentum must stay zero.", "2": "This multiplies instead of dividing by the mass.", "3": "Both moving the same way would give non-zero total momentum."}'),
  ('PHY-6014', 'Force and motion', 'Newton''s third law and momentum', 'moderate', 'PMDC MDCAT 2025 Physics 2.14–2.17; NUMS MDCAT 2026 Physics 1.14–1.17', 'Why does Newton''s third law lead to conservation of momentum when two bodies collide?', '["Each body exerts an equal and opposite force on the other for the same time, so their momentum changes are equal and opposite.", "The bodies always stop after colliding.", "The heavier body always pushes harder.", "Friction cancels all forces."]', 0, 'F₁₂ = −F₂₁ act for the same Δt, so Δp₁ = −Δp₂ and the total momentum of the pair does not change.', '{"1": "Bodies usually keep moving after a collision.", "2": "The forces are always equal in size.", "3": "Momentum is conserved because of the mutual forces, not friction."}'),
  ('PHY-6015', 'Force and motion', 'Elastic collisions', 'hard', 'PMDC MDCAT 2025 Physics 2.14–2.17; NUMS MDCAT 2026 Physics 1.14–1.17', 'Ball A moving at 5 m s⁻¹ collides head-on and perfectly elastically with ball B at rest. Afterwards B moves forward at 4 m s⁻¹. What is A''s velocity after the collision?', '["1 m s⁻¹ forward", "4 m s⁻¹ forward", "zero", "1 m s⁻¹ backward"]', 3, 'In a perfectly elastic collision the relative speed of approach equals the relative speed of separation: 5 = v_B − v_A = 4 − v_A, so v_A = −1 m s⁻¹ (backward).', '{"0": "Then the separation speed would be 3 m s⁻¹, not 5 m s⁻¹.", "1": "Then the balls would not separate at all.", "2": "A would stop only if the masses were equal, in which case B would move at 5 m s⁻¹."}'),
  ('PHY-6016', 'Force and motion', 'Elastic collisions', 'moderate', 'PMDC MDCAT 2025 Physics 2.14–2.17; NUMS MDCAT 2026 Physics 1.14–1.17', 'Two balls of equal mass collide head-on, perfectly elastically. One was at rest. After the collision', '["both move together with half the speed", "both rebound with the original speed", "they exchange velocities: the moving ball stops and the other moves off with its speed", "the moving ball continues with half its speed"]', 2, 'For equal masses in a one-dimensional elastic collision, the velocities are simply exchanged.', '{"0": "Moving together happens in a perfectly inelastic collision.", "1": "This would create momentum and kinetic energy.", "3": "This would not conserve kinetic energy and momentum together."}'),
  ('PHY-6017', 'Force and motion', 'Inelastic collisions', 'hard', 'PMDC MDCAT 2025 Physics 2.14–2.17; NUMS MDCAT 2026 Physics 1.14–1.17', 'A 2 kg trolley moving at 3 m s⁻¹ hits a 1 kg trolley at rest and they stick together. How much kinetic energy is lost?', '["0 J", "3 J", "6 J", "9 J"]', 1, 'Common velocity = (2 × 3)/3 = 2 m s⁻¹. KE before = ½ × 2 × 9 = 9 J; KE after = ½ × 3 × 4 = 6 J; loss = 3 J (to heat, sound and deformation).', '{"0": "Kinetic energy is not conserved in a perfectly inelastic collision.", "2": "6 J is the kinetic energy remaining, not lost.", "3": "9 J is the initial kinetic energy."}'),
  ('PHY-6018', 'Work and energy', 'Work against friction', 'easy', 'PMDC MDCAT 2025 Physics 3.5–3.8; NUMS MDCAT 2026 Physics 2.5–2.8', 'A box is pushed 5 m across a rough floor at constant speed against a friction force of 20 N. The energy dissipated as heat is', '["100 J", "4 J", "25 J", "zero, because the speed is constant"]', 0, 'Work done against friction = f × d = 20 × 5 = 100 J; this energy is dissipated as heat in the box, floor and surroundings.', '{"1": "This divides force by distance.", "2": "This adds force and distance.", "3": "Constant speed means no gain in KE, but work against friction is still done."}'),
  ('PHY-6019', 'Work and energy', 'Power', 'moderate', 'PMDC MDCAT 2025 Physics 3.5–3.8; NUMS MDCAT 2026 Physics 2.5–2.8', 'A car moves at a constant 20 m s⁻¹ against a total resistive force of 1500 N. The power developed by its engine is', '["75 W", "3 kW", "300 kW", "30 kW"]', 3, 'At constant speed the driving force equals the resistance, and P = F·v = 1500 × 20 = 30 000 W = 30 kW.', '{"0": "This divides force by speed.", "1": "This is ten times too small.", "2": "This is ten times too large."}'),
  ('PHY-6020', 'Work and energy', 'Efficiency', 'easy', 'PMDC MDCAT 2025 Physics 3.5–3.8; NUMS MDCAT 2026 Physics 2.5–2.8', 'An electric motor takes 500 W of electrical power and delivers 400 W of mechanical power. Its efficiency and the power wasted are', '["125%, 100 W", "80%, 400 W", "80%, 100 W", "20%, 100 W"]', 2, 'Efficiency = useful output/input = 400/500 = 80%. The remaining 100 W is wasted, mainly as heat and sound.', '{"0": "Efficiency can never exceed 100%.", "1": "400 W is the useful output, not the waste.", "3": "20% is the fraction wasted."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Physics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PHY-6021', 'Work and energy', 'Gravitational potential energy', 'moderate', 'PMDC MDCAT 2025 Physics 3.5–3.8; NUMS MDCAT 2026 Physics 2.5–2.8', 'Taking ground level as the zero of gravitational potential energy, what is the potential energy of a 2 kg stone lying at the bottom of a pit 2 m deep? (g = 10 m s⁻²)', '["+40 J", "−40 J", "zero", "−4 J"]', 1, 'PE = mgh with h measured from the reference level. The stone is 2 m below it, so PE = 2 × 10 × (−2) = −40 J.', '{"0": "The stone is below the reference level, so its PE is negative.", "2": "PE is zero only at the reference level.", "3": "This leaves out g."}'),
  ('PHY-6022', 'Fluid dynamics', 'Terminal velocity', 'easy', 'PMDC MDCAT 2025 Physics 5.1–5.10', 'A small steel ball falling through oil reaches terminal velocity when', '["the upward drag (plus upthrust) balances its weight, so the net force is zero", "its weight becomes zero", "it stops moving", "the oil stops exerting any force"]', 0, 'Drag grows with speed until drag + upthrust = weight. With zero net force there is no acceleration, so the ball falls at constant (terminal) velocity.', '{"1": "Weight does not change.", "2": "At terminal velocity it keeps moving at a constant speed.", "3": "The fluid exerts the drag and upthrust that balance the weight."}'),
  ('PHY-6023', 'Fluid dynamics', 'Stokes'' law', 'hard', 'PMDC MDCAT 2025 Physics 5.1–5.10', 'For a small sphere falling through a viscous fluid (Stokes'' law, F = 6πηrv), the terminal velocity is proportional to r². If the radius is doubled, the terminal velocity becomes', '["half", "double", "unchanged", "four times"]', 3, 'Weight ∝ r³ while drag ∝ r v, so at terminal velocity v ∝ r³/r = r². Doubling r gives 2² = 4 times the terminal velocity.', '{"0": "A larger sphere falls faster, not slower.", "1": "This ignores that weight grows as r³.", "2": "The terminal velocity depends on the radius."}'),
  ('PHY-6024', 'Fluid dynamics', 'Turbulent flow', 'easy', 'PMDC MDCAT 2025 Physics 5.1–5.10', 'Which statement about turbulent flow is correct?', '["It occurs only at very low speeds.", "The fluid moves in smooth parallel layers.", "It is irregular, with eddies, and sets in when the flow speed is high enough; most practical flows are turbulent.", "It never occurs in blood vessels."]', 2, 'Above a critical speed, laminar (streamline) flow breaks into irregular eddying flow. Most everyday flows (rivers, air around cars) are turbulent.', '{"0": "Low speeds favour laminar flow.", "1": "That describes laminar (streamline) flow.", "3": "Turbulence can occur in arteries, e.g. near narrowed sections."}'),
  ('PHY-6025', 'Fluid dynamics', 'Equation of continuity', 'moderate', 'PMDC MDCAT 2025 Physics 5.1–5.10', 'Water flows at 2 m s⁻¹ through a pipe of cross-sectional area 4 cm², which narrows to 1 cm². The speed in the narrow part is', '["0.5 m s⁻¹", "8 m s⁻¹", "2 m s⁻¹", "4 m s⁻¹"]', 1, 'Continuity (conservation of mass for an incompressible fluid): A₁v₁ = A₂v₂, so v₂ = (4 × 2)/1 = 8 m s⁻¹.', '{"0": "This inverts the area ratio.", "2": "The speed must change when the area changes.", "3": "This doubles instead of multiplying by four."}'),
  ('PHY-6026', 'Fluid dynamics', 'Bernoulli''s effect in blood flow', 'moderate', 'PMDC MDCAT 2025 Physics 5.1–5.10', 'An artery is narrowed by a fatty deposit. By the equation of continuity and Bernoulli''s principle, in the narrowed part the blood', '["moves faster and its pressure falls", "moves more slowly and its pressure rises", "moves faster and its pressure rises", "stops flowing"]', 0, 'A smaller area means a higher speed (Av constant); by Bernoulli''s principle the pressure is lower where the speed is higher. The low pressure can cause the artery to narrow further.', '{"1": "Speed increases, not decreases, in a narrower section.", "2": "Higher speed goes with lower pressure.", "3": "Blood still flows, faster, through the narrowing."}'),
  ('PHY-6027', 'Waves', 'Mechanical and electromagnetic waves', 'easy', 'PMDC MDCAT 2025 Physics 6.2, 6.6; NUMS MDCAT 2026 Physics 4.2, 4.6', 'A ringing bell inside a jar can be seen but not heard when the air is pumped out because', '["light is a mechanical wave", "sound travels faster than light", "glass stops sound but not light", "sound needs a material medium, while light (an electromagnetic wave) does not"]', 3, 'Sound travels by vibrations of particles of a medium; in a vacuum there are no particles. Electromagnetic waves are self-sustaining electric and magnetic fields that need no medium.', '{"0": "Light is an electromagnetic wave.", "1": "Light is far faster than sound.", "2": "The sound fades as the air is removed, before any change to the glass."}'),
  ('PHY-6028', 'Waves', 'Transverse and longitudinal waves', 'moderate', 'PMDC MDCAT 2025 Physics 6.2, 6.6; NUMS MDCAT 2026 Physics 4.2, 4.6', 'Sound waves in air cannot be polarised because they are', '["transverse", "electromagnetic", "longitudinal", "too fast"]', 2, 'Only transverse waves, whose vibrations are perpendicular to the direction of travel, can be polarised. In sound waves the air particles vibrate along the direction of travel.', '{"0": "Transverse waves can be polarised.", "1": "Sound is a mechanical wave.", "3": "Speed has nothing to do with polarisation."}'),
  ('PHY-6029', 'Waves', 'Newton''s formula for the speed of sound', 'moderate', 'PMDC MDCAT 2025 Physics 6.7–6.9; NUMS MDCAT 2026 Physics 4.7–4.9', 'Newton''s formula v = √(P/ρ) gave about 280 m s⁻¹ for sound in air at 0 °C, well below the measured 332 m s⁻¹. His mistake was to assume that', '["air is incompressible", "the compressions and rarefactions occur at constant temperature (isothermally)", "sound is a transverse wave", "the density of air is zero"]', 1, 'Compressions and rarefactions are too fast for heat to flow in or out, so the changes are adiabatic, not isothermal. Laplace corrected this by using γP instead of P.', '{"0": "Sound depends on air being compressible.", "2": "Newton treated sound as a longitudinal pressure wave.", "3": "He used the correct density."}'),
  ('PHY-6030', 'Waves', 'Laplace''s correction', 'moderate', 'PMDC MDCAT 2025 Physics 6.7–6.9; NUMS MDCAT 2026 Physics 4.7–4.9', 'With Laplace''s correction, the speed of sound in a gas is', '["v = √(γP/ρ)", "v = √(P/ρ)", "v = γ√(P/ρ)", "v = √(ρ/γP)"]', 0, 'For adiabatic changes the elasticity is γP, so v = √(γP/ρ). For air γ ≈ 1.4, giving about 332 m s⁻¹ at 0 °C.', '{"1": "This is Newton''s original formula.", "2": "γ must be inside the square root.", "3": "This inverts the formula."}'),
  ('PHY-6031', 'Waves', 'Factors affecting the speed of sound', 'moderate', 'PMDC MDCAT 2025 Physics 6.7–6.9; NUMS MDCAT 2026 Physics 4.7–4.9', 'If the pressure of air is doubled while its temperature is kept constant, the speed of sound in it', '["doubles", "becomes √2 times", "halves", "is unchanged"]', 3, 'At constant temperature P/ρ is constant (doubling P doubles ρ), so v = √(γP/ρ) is unchanged.', '{"0": "Density doubles along with pressure.", "1": "This ignores the increase in density.", "2": "The speed does not depend on pressure at constant temperature."}'),
  ('PHY-6032', 'Waves', 'Factors affecting the speed of sound', 'moderate', 'PMDC MDCAT 2025 Physics 6.7–6.9; NUMS MDCAT 2026 Physics 4.7–4.9', 'The speed of sound in air is 332 m s⁻¹ at 0 °C and increases by about 0.61 m s⁻¹ per °C. At 20 °C it is about', '["332 m s⁻¹", "352 m s⁻¹", "344 m s⁻¹", "320 m s⁻¹"]', 2, 'v = 332 + 0.61 × 20 = 332 + 12.2 ≈ 344 m s⁻¹.', '{"0": "The speed increases with temperature.", "1": "This adds 1 m s⁻¹ per °C.", "3": "The speed does not fall when air is warmed."}'),
  ('PHY-6033', 'Waves', 'Factors affecting the speed of sound', 'moderate', 'PMDC MDCAT 2025 Physics 6.7–6.9; NUMS MDCAT 2026 Physics 4.7–4.9', 'Sound travels slightly faster in humid air than in dry air at the same temperature and pressure because', '["water vapour is denser than dry air", "humid air is less dense, since water molecules (M = 18) are lighter than N₂ and O₂", "humidity lowers the temperature", "water molecules carry sound energy faster by colliding harder"]', 1, 'v ∝ 1/√ρ. Replacing some N₂ (28) and O₂ (32) with lighter H₂O (18) lowers the density of air, so sound travels faster.', '{"0": "Water vapour is less dense than dry air at the same conditions.", "2": "Humidity does not lower temperature in this comparison.", "3": "The effect is due to lower density."}'),
  ('PHY-6034', 'Waves', 'Factors affecting the speed of sound', 'hard', 'PMDC MDCAT 2025 Physics 6.7–6.9; NUMS MDCAT 2026 Physics 4.7–4.9', 'The speed of sound in a gas is v at absolute temperature T. At absolute temperature 4T it will be', '["2v", "v/2", "v", "4v"]', 0, 'v ∝ √T, so at 4T the speed is √4 = 2 times greater.', '{"1": "The speed increases, not decreases, with temperature.", "2": "The speed depends on temperature.", "3": "v depends on the square root of T."}'),
  ('PHY-6035', 'Waves', 'SHM and circular motion', 'moderate', 'PMDC MDCAT 2025 Physics 6.17–6.18', 'A point moves round a circle of radius A at constant angular speed ω. Its projection on a diameter', '["moves with constant speed Aω", "performs SHM with amplitude 2A", "stays at rest at the centre", "performs SHM with amplitude A and angular frequency ω"]', 3, 'The projection x = A cos ωt oscillates between −A and +A with acceleration −ω²x, which is simple harmonic motion.', '{"0": "The projection speeds up near the centre and stops at the ends.", "1": "It moves from −A to +A, so the amplitude is A (the path length is 2A).", "2": "It moves to and fro along the diameter."}'),
  ('PHY-6036', 'Waves', 'SHM and circular motion', 'hard', 'PMDC MDCAT 2025 Physics 6.17–6.18', 'For the projection of uniform circular motion (radius A, angular speed ω) on a diameter, where is the speed of the projection greatest and what is its value?', '["At the ends of the diameter; Aω", "At the centre; Aω²", "At the centre; Aω", "At the ends; zero acceleration"]', 2, 'At the centre the velocity of the circling point is parallel to the diameter, so the projection has the full speed Aω; at the ends its speed is zero and its acceleration is greatest (ω²A).', '{"0": "At the ends the projection is momentarily at rest.", "1": "Aω² is the maximum acceleration, which occurs at the ends.", "3": "The acceleration is greatest, not zero, at the ends."}'),
  ('PHY-6037', 'Thermodynamics', 'Thermal equilibrium', 'moderate', 'PMDC MDCAT 2025 Physics 7.1–7.7; NUMS MDCAT 2026 Physics 5.1–5.7', 'A small cup of boiling water is placed in a large tub of water at 20 °C. The tub has far more internal energy than the cup. Heat flows', '["from the tub to the cup, because the tub has more internal energy", "from the cup to the tub, because the cup is at the higher temperature", "in neither direction", "from the tub to the cup until both have equal internal energy"]', 1, 'Heat flows from a region of higher temperature to one of lower temperature, whatever their total internal energies, until thermal equilibrium (equal temperature) is reached.', '{"0": "Direction of heat flow depends on temperature, not total internal energy.", "2": "There is a temperature difference, so heat flows.", "3": "Equilibrium means equal temperatures, not equal internal energies."}'),
  ('PHY-6038', 'Thermodynamics', 'Specific heat and molar specific heat', 'moderate', 'PMDC MDCAT 2025 Physics 7.1–7.7; NUMS MDCAT 2026 Physics 5.1–5.7', 'The specific heat of water is 4200 J kg⁻¹ K⁻¹ and its molar mass is 0.018 kg mol⁻¹. Its molar specific heat is about', '["75.6 J mol⁻¹ K⁻¹", "4200 J mol⁻¹ K⁻¹", "233 000 J mol⁻¹ K⁻¹", "18 J mol⁻¹ K⁻¹"]', 0, 'Molar specific heat = M × c = 0.018 × 4200 ≈ 75.6 J mol⁻¹ K⁻¹. Specific heat is per kilogram; molar specific heat is per mole.', '{"1": "This is the specific heat per kilogram.", "2": "This divides by the molar mass instead of multiplying.", "3": "This is the molar mass in g mol⁻¹."}'),
  ('PHY-6039', 'Thermodynamics', 'Molar specific heats of a gas', 'moderate', 'PMDC MDCAT 2025 Physics 7.1–7.7; NUMS MDCAT 2026 Physics 5.1–5.7', 'For a gas, the molar specific heat at constant pressure (Cp) is greater than that at constant volume (Cv) because at constant pressure', '["the molecules are heavier", "no work is done", "the gas loses heat", "the gas does work as it expands, so extra heat is needed for the same temperature rise"]', 3, 'At constant volume all the heat raises internal energy. At constant pressure some heat is also used to do expansion work PΔV, so more heat is needed per kelvin.', '{"0": "Molecular mass does not change.", "1": "Work is done at constant pressure, not at constant volume.", "2": "Heat is supplied, not lost."}'),
  ('PHY-6040', 'Thermodynamics', 'Work done by a gas', 'moderate', 'PMDC MDCAT 2025 Physics 7.1–7.7; NUMS MDCAT 2026 Physics 5.1–5.7', 'A gas expands at a constant pressure of 2.0 × 10⁵ Pa from 1.0 L to 3.0 L. The work done by the gas is', '["200 J", "600 J", "400 J", "4 × 10⁵ J"]', 2, 'W = PΔV = 2.0 × 10⁵ × (3.0 − 1.0) × 10⁻³ m³ = 400 J.', '{"0": "This uses a volume change of 1 L.", "1": "This uses the final volume instead of the change.", "3": "Litres must be converted to m³."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Physics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PHY-6041', 'Thermodynamics', 'First law of thermodynamics', 'moderate', 'PMDC MDCAT 2025 Physics 7.1–7.7; NUMS MDCAT 2026 Physics 5.1–5.7', 'A gas absorbs 500 J of heat and does 200 J of work in expanding. The change in its internal energy is', '["+700 J", "+300 J", "−300 J", "−700 J"]', 1, 'Q = ΔU + W, so ΔU = 500 − 200 = +300 J.', '{"0": "This adds the work done by the gas.", "2": "The gas gains more energy than it gives out.", "3": "Both quantities have the wrong sign."}'),
  ('PHY-6042', 'Thermodynamics', 'First law of thermodynamics', 'moderate', 'PMDC MDCAT 2025 Physics 7.1–7.7; NUMS MDCAT 2026 Physics 5.1–5.7', 'A gas is heated in a rigid sealed container. According to the first law of thermodynamics', '["all the heat supplied increases its internal energy", "all the heat supplied is used to do work", "its internal energy does not change", "its temperature falls"]', 0, 'In an isochoric (constant-volume) process ΔV = 0, so W = 0 and Q = ΔU.', '{"1": "No work is done when the volume cannot change.", "2": "The internal energy rises by the heat supplied.", "3": "Temperature rises with internal energy."}'),
  ('PHY-6043', 'Thermodynamics', 'Cp − Cv = R', 'hard', 'PMDC MDCAT 2025 Physics 7.1–7.7; NUMS MDCAT 2026 Physics 5.1–5.7', 'For a monatomic ideal gas Cv = (3/2)R. Using Cp − Cv = R, the ratio γ = Cp/Cv is', '["1.40", "1.33", "1.50", "1.67"]', 3, 'Cp = (3/2)R + R = (5/2)R, so γ = (5/2)/(3/2) = 5/3 ≈ 1.67.', '{"0": "1.40 is γ for a diatomic gas such as air.", "1": "1.33 is γ for some polyatomic gases.", "2": "This uses Cp = 3R/2 + 3R/4."}'),
  ('PHY-6044', 'Thermodynamics', 'Cp − Cv = R', 'easy', 'PMDC MDCAT 2025 Physics 7.1–7.7; NUMS MDCAT 2026 Physics 5.1–5.7', 'For one mole of any ideal gas, the difference Cp − Cv is equal to', '["zero", "4.18 J mol⁻¹ K⁻¹", "8.31 J mol⁻¹ K⁻¹", "1.67"]', 2, 'Cp − Cv = R = 8.31 J mol⁻¹ K⁻¹; the extra heat at constant pressure equals the work done, PΔV = RΔT per mole.', '{"0": "The two heat capacities are not equal for a gas.", "1": "4.18 J is the mechanical equivalent of a calorie.", "3": "1.67 is the ratio Cp/Cv for a monatomic gas, not the difference."}'),
  ('PHY-6045', 'Electrostatics', 'Field due to two charges', 'easy', 'PMDC MDCAT 2025 Physics 8.1–8.5; NUMS MDCAT 2026 Physics 6.1–6.5', 'Two equal positive charges are placed a short distance apart. The electric field at the midpoint between them is', '["twice the field of one charge", "zero", "directed towards either charge", "infinite"]', 1, 'Each charge produces a field of equal magnitude at the midpoint, pointing away from itself; the two fields are in opposite directions and cancel.', '{"0": "The fields are opposite, not in the same direction.", "2": "The resultant is zero, so it has no direction.", "3": "The point is at a finite distance from both charges."}'),
  ('PHY-6046', 'Electrostatics', 'Field due to two charges', 'hard', 'PMDC MDCAT 2025 Physics 8.1–8.5; NUMS MDCAT 2026 Physics 6.1–6.5', 'Charges +q and −q are a distance d apart. The electric field at the midpoint is', '["8kq/d², towards −q", "zero", "kq/d², towards +q", "4kq/d², towards +q"]', 0, 'Each charge is d/2 away, giving kq/(d/2)² = 4kq/d². Both fields point towards −q (away from +q, towards −q), so they add: 8kq/d².', '{"1": "Fields from opposite charges add at the midpoint.", "2": "This uses the full distance d and the wrong direction.", "3": "This counts only one charge and the wrong direction."}'),
  ('PHY-6047', 'Electrostatics', 'Field due to two charges', 'hard', 'PMDC MDCAT 2025 Physics 8.1–8.5; NUMS MDCAT 2026 Physics 6.1–6.5', 'Charges +4q and +q are 3 m apart. At what distance from the +4q charge, on the line joining them, is the electric field zero?', '["1 m", "1.5 m", "2.5 m", "2 m"]', 3, 'k(4q)/x² = kq/(3 − x)² ⇒ 2/x = 1/(3 − x) ⇒ x = 2 m. The null point is nearer the smaller charge.', '{"0": "At 1 m the field of +4q is 16 times that of +q, so they do not cancel.", "1": "The midpoint is not the null point for unequal charges.", "2": "At 2.5 m the field of +q is larger."}'),
  ('PHY-6048', 'Electrostatics', 'Electric field lines', 'moderate', 'PMDC MDCAT 2025 Physics 8.1–8.5; NUMS MDCAT 2026 Physics 6.1–6.5', 'Field lines drawn for two equal positive point charges', '["go from one charge to the other", "cross each other at the midpoint", "start on both charges and bend away from each other, leaving a neutral point midway", "form closed loops around each charge"]', 2, 'Lines start on positive charges and end at infinity (or on negative charges). For like charges they repel each other, and no line passes through the neutral point midway.', '{"0": "That pattern is for a positive and a negative charge.", "1": "Field lines never cross.", "3": "Electrostatic field lines do not form closed loops."}'),
  ('PHY-6049', 'Electrostatics', 'Field of an infinite sheet', 'moderate', 'PMDC MDCAT 2025 Physics 8.1–8.5; NUMS MDCAT 2026 Physics 6.1–6.5', 'The electric field near a very large (infinite) plane sheet carrying uniform surface charge density σ', '["decreases as 1/r²", "is σ/2ε₀ and does not depend on distance from the sheet", "is zero", "increases with distance"]', 1, 'By Gauss''s law the field of an infinite sheet is uniform, E = σ/2ε₀, perpendicular to the sheet on both sides.', '{"0": "1/r² applies to a point charge.", "2": "A charged sheet does produce a field.", "3": "The field is the same at all distances."}'),
  ('PHY-6050', 'Electrostatics', 'Field between parallel plates', 'moderate', 'PMDC MDCAT 2025 Physics 8.1–8.5; NUMS MDCAT 2026 Physics 6.1–6.5', 'Between two large parallel plates carrying equal and opposite charge densities ±σ, the electric field is', '["σ/ε₀, uniform and directed from the positive to the negative plate", "zero", "σ/2ε₀", "2σ/ε₀"]', 0, 'Each plate contributes σ/2ε₀; between the plates the two fields add to σ/ε₀, while outside they cancel.', '{"1": "The fields cancel outside the plates, not between them.", "2": "This is the field of one sheet.", "3": "This double-counts both sheets."}'),
  ('PHY-6051', 'Electrostatics', 'Coulomb''s law in a medium', 'moderate', 'PMDC MDCAT 2025 Physics 8.1–8.5; NUMS MDCAT 2026 Physics 6.1–6.5', 'The force between two point charges in air is F. If they are placed in water (relative permittivity about 80) at the same separation, the force becomes about', '["80F", "F", "F/√80", "F/80"]', 3, 'F = q₁q₂/(4πε₀εᵣr²); the medium reduces the force by the factor εᵣ.', '{"0": "A medium reduces, not increases, the force.", "1": "The medium does change the force.", "2": "The force is divided by εᵣ itself."}'),
  ('PHY-6052', 'Current electricity', 'Ohm''s law', 'easy', 'PMDC MDCAT 2025 Physics 9.2–9.5; NUMS MDCAT 2026 Physics 7.2–7.5', 'Ohm''s law (V ∝ I) holds for a metallic conductor only if', '["the current is very large", "it is made of a semiconductor", "its temperature and other physical conditions stay constant", "the voltage is alternating"]', 2, 'Resistance changes with temperature, so V/I is constant only when the physical state, especially temperature, stays the same.', '{"0": "Large currents heat the conductor and change its resistance.", "1": "Semiconductors are non-ohmic.", "3": "Alternating voltage is not a condition of Ohm''s law."}'),
  ('PHY-6053', 'Current electricity', 'Ohm''s law', 'moderate', 'PMDC MDCAT 2025 Physics 9.2–9.5; NUMS MDCAT 2026 Physics 7.2–7.5', 'The I–V graph of a filament lamp curves (bends towards the V axis) at higher voltages because', '["the filament''s resistance falls as it heats up", "the filament''s resistance rises as it heats up", "the lamp obeys Ohm''s law exactly", "the current becomes zero"]', 1, 'As current increases the tungsten filament gets hotter, its resistance rises, and the current increases less than in proportion to the voltage, so the lamp is non-ohmic.', '{"0": "The resistance of a metal rises with temperature.", "2": "A curved I–V graph means it does not obey Ohm''s law.", "3": "Current still flows, just less than proportionally."}'),
  ('PHY-6054', 'Current electricity', 'Maximum power transfer', 'moderate', 'PMDC MDCAT 2025 Physics 9.2–9.5; NUMS MDCAT 2026 Physics 7.2–7.5', 'A battery of emf 12 V and internal resistance 2 Ω is connected to a variable external resistor R. The maximum power delivered to R is', '["18 W", "72 W", "36 W", "6 W"]', 0, 'Maximum power is transferred when R = r = 2 Ω. Then I = 12/4 = 3 A and P = I²R = 9 × 2 = 18 W (= E²/4r).', '{"1": "This is E²/r, the short-circuit power dissipated inside the battery.", "2": "This is E²/2r.", "3": "6 is E/r, the short-circuit current in amperes, not a power."}'),
  ('PHY-6055', 'Current electricity', 'Maximum power transfer', 'moderate', 'PMDC MDCAT 2025 Physics 9.2–9.5; NUMS MDCAT 2026 Physics 7.2–7.5', 'Power stations are NOT designed for maximum power transfer to the load because, under that condition,', '["no current flows", "the load voltage is equal to the emf", "the internal resistance becomes zero", "the efficiency is only 50%: as much power is wasted in the source as is delivered"]', 3, 'When R = r the same current flows through both, so half the total power is lost in the internal resistance.', '{"0": "Current does flow (I = E/2r).", "1": "The load voltage is only half the emf.", "2": "Internal resistance is fixed by the source."}'),
  ('PHY-6056', 'Current electricity', 'Electric power and kWh', 'easy', 'NUMS MDCAT 2026 Physics 7 (kilowatt-hour)', 'A 2 kW heater is used for 3 hours. The energy used, and its cost at Rs 50 per unit, are', '["6 kWh, Rs 150", "1.5 kWh, Rs 75", "6 kWh, Rs 300", "5 kWh, Rs 250"]', 2, 'Energy = power × time = 2 kW × 3 h = 6 kWh (6 units). Cost = 6 × 50 = Rs 300.', '{"0": "The cost uses Rs 25 per unit.", "1": "This divides power by time.", "3": "This adds power and time."}'),
  ('PHY-6057', 'Current electricity', 'Electric power and kWh', 'easy', 'NUMS MDCAT 2026 Physics 7 (kilowatt-hour)', 'One kilowatt-hour is equal to', '["1000 J", "3.6 × 10⁶ J", "3600 J", "3.6 × 10³ kJ per second"]', 1, '1 kWh = 1000 W × 3600 s = 3.6 × 10⁶ J. It is a unit of energy, not power.', '{"0": "1000 J is one kilowatt for one second.", "2": "3600 J is one watt-hour.", "3": "kJ per second is a unit of power."}'),
  ('PHY-6058', 'Electromagnetism', 'Magnetic flux density', 'easy', 'PMDC MDCAT 2025 Physics 10.1–10.4; NUMS MDCAT 2026 Physics 8.1–8.4', 'One tesla is equal to', '["1 N A⁻¹ m⁻¹", "1 N A m", "1 Wb m", "1 A m⁻¹"]', 0, 'From F = BIL, B = F/IL, so 1 T = 1 N/(1 A × 1 m) = 1 N A⁻¹ m⁻¹ (= 1 Wb m⁻²).', '{"1": "The units of current and length should be in the denominator.", "2": "1 T is 1 Wb m⁻², not Wb m.", "3": "A m⁻¹ is the unit of magnetic field strength H, not B."}'),
  ('PHY-6059', 'Electromagnetism', 'Charged particle in a magnetic field', 'moderate', 'PMDC MDCAT 2025 Physics 10.1–10.4; NUMS MDCAT 2026 Physics 8.1–8.4', 'A charged particle enters a uniform magnetic field at right angles to it and moves in a circle of radius r. If its speed is doubled, the radius becomes', '["r/2", "r", "4r", "2r"]', 3, 'qvB = mv²/r gives r = mv/qB, so r is proportional to v.', '{"0": "A faster particle bends less sharply.", "1": "The radius depends on speed.", "2": "r is proportional to v, not v²."}'),
  ('PHY-6060', 'Electromagnetism', 'Charged particle in a magnetic field', 'hard', 'PMDC MDCAT 2025 Physics 10.1–10.4; NUMS MDCAT 2026 Physics 8.1–8.4', 'For a charged particle moving in a circle in a uniform magnetic field, the time for one revolution, T = 2πm/qB,', '["increases with speed", "decreases with speed", "does not depend on speed", "depends on the radius only"]', 2, 'T = 2πr/v = 2π(mv/qB)/v = 2πm/qB. A faster particle moves in a proportionally larger circle, so the period is unchanged (the principle of the cyclotron).', '{"0": "Larger radius and higher speed cancel.", "1": "The period is independent of speed.", "3": "The radius cancels out of the period."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Physics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PHY-6061', 'Electromagnetism', 'Force on a moving charge', 'easy', 'PMDC MDCAT 2025 Physics 10.1–10.4; NUMS MDCAT 2026 Physics 8.1–8.4', 'A charged particle moves parallel to a uniform magnetic field. The magnetic force on it is', '["qvB", "zero", "qvB/2", "directed along the field"]', 1, 'F = qvB sin θ, and θ = 0° for motion along the field, so F = 0 and the particle continues in a straight line.', '{"0": "qvB is the force for motion perpendicular to the field.", "2": "sin 0° = 0, so there is no force.", "3": "The magnetic force is never along the field."}'),
  ('PHY-6062', 'Electromagnetism', 'Force on a moving charge', 'moderate', 'PMDC MDCAT 2025 Physics 10.1–10.4; NUMS MDCAT 2026 Physics 8.1–8.4', 'The magnetic force on a moving charged particle does no work on it because', '["the force is always perpendicular to its velocity", "the force is always zero", "the charge is too small", "the field is uniform"]', 0, 'Since F = q(v × B) is perpendicular to v, it changes only the direction of motion; the speed and kinetic energy stay constant.', '{"1": "The force is not zero unless v is parallel to B.", "2": "Charge size does not matter.", "3": "Work is zero even in non-uniform fields."}'),
  ('PHY-6063', 'Electromagnetic induction', 'Transformer', 'moderate', 'PMDC MDCAT 2025 Physics 11.3–11.4; NUMS MDCAT 2026 Physics 9.3–9.5', 'The core of a transformer is made of thin, insulated sheets (laminations) of soft iron to', '["increase eddy currents", "make the transformer work on DC", "increase the resistance of the coils", "reduce energy loss due to eddy currents"]', 3, 'Laminations break up the paths of eddy currents induced in the core, greatly reducing heating losses; soft iron also reduces hysteresis loss.', '{"0": "Eddy currents waste energy as heat.", "1": "A transformer cannot work on steady DC.", "2": "The coils are copper; laminations are in the core."}'),
  ('PHY-6064', 'Electromagnetic induction', 'Transformer', 'easy', 'PMDC MDCAT 2025 Physics 11.3–11.4; NUMS MDCAT 2026 Physics 9.3–9.5', 'A transformer reduces 220 V to 11 V. Its primary coil has 2000 turns. The secondary coil has', '["200 turns", "40 000 turns", "100 turns", "1100 turns"]', 2, 'Vs/Vp = Ns/Np, so Ns = 2000 × 11/220 = 100 turns.', '{"0": "This uses 22 V instead of 11 V.", "1": "This is a step-up ratio.", "3": "This uses half the primary turns."}'),
  ('PHY-6065', 'Electromagnetic induction', 'Transformer', 'moderate', 'PMDC MDCAT 2025 Physics 11.3–11.4; NUMS MDCAT 2026 Physics 9.3–9.5', 'A transformer does not work with a steady DC supply because', '["DC is too weak", "a steady current produces an unchanging magnetic flux, so no emf is induced in the secondary", "the iron core melts", "DC flows only in the secondary"]', 1, 'By Faraday''s law an emf is induced only when the flux linking the secondary changes; AC gives a continuously changing flux.', '{"0": "Even a large DC gives no induced emf once steady.", "2": "The core does not melt.", "3": "DC in the primary would not reach the secondary."}'),
  ('PHY-6066', 'Electromagnetic induction', 'Power transmission', 'moderate', 'PMDC MDCAT 2025 Physics 11.3–11.4; NUMS MDCAT 2026 Physics 9.3–9.5', 'The same power is transmitted through the same cables, but the voltage is stepped up ten times. The power lost as heat in the cables becomes', '["1/100 of the original", "10 times greater", "1/10 of the original", "unchanged"]', 0, 'For the same power P = VI, ten times the voltage means one tenth of the current. Loss = I²R, so it falls to (1/10)² = 1/100.', '{"1": "Raising voltage lowers current and losses.", "2": "Loss depends on I², not I.", "3": "Lower current reduces I²R loss."}'),
  ('PHY-6067', 'Electromagnetic induction', 'Power transmission', 'easy', 'PMDC MDCAT 2025 Physics 11.3–11.4; NUMS MDCAT 2026 Physics 9.3–9.5', 'In a power distribution system, step-up transformers are used at the power station and step-down transformers near homes because', '["high voltage is safer inside homes", "step-down transformers generate electricity", "cables cannot carry low voltage", "transmission at high voltage and low current reduces energy loss in long cables, while homes need a safe lower voltage"]', 3, 'Low current in the long transmission lines keeps I²R losses small; near consumers the voltage is reduced to a safe level, e.g. 220 V.', '{"0": "High voltage is dangerous in homes.", "1": "Transformers only change voltage; they do not generate energy.", "2": "Cables can carry any voltage; the issue is energy loss."}'),
  ('PHY-6068', 'Electromagnetic induction', 'AC generator', 'moderate', 'PMDC MDCAT 2025 Physics 11.3–11.4; NUMS MDCAT 2026 Physics 9.3–9.5', 'In an AC generator (N turns, area A, field B, angular speed ω), the induced emf is ε = NBAω sin ωt. The emf is maximum when the plane of the coil is', '["perpendicular to the magnetic field", "at 45° to the field", "parallel to the magnetic field", "moving along the field"]', 2, 'When the coil''s plane is parallel to B, its sides cut the field lines at right angles, so the flux linkage changes fastest and ε = NBAω (even though the flux through it is zero at that instant).', '{"0": "In this position the flux is maximum but changing least, so ε = 0.", "1": "At 45° the emf is only about 71% of maximum.", "3": "Moving along the field cuts no field lines."}'),
  ('PHY-6069', 'Electromagnetic induction', 'AC generator', 'easy', 'PMDC MDCAT 2025 Physics 11.3–11.4; NUMS MDCAT 2026 Physics 9.3–9.5', 'An AC generator converts', '["electrical energy into mechanical energy", "mechanical energy into electrical energy", "chemical energy into electrical energy", "heat into light"]', 1, 'A coil is rotated by mechanical means (turbine, engine) in a magnetic field, inducing an alternating emf by electromagnetic induction.', '{"0": "This is what a motor does.", "2": "This is what a cell does.", "3": "This is what a lamp does."}'),
  ('PHY-6070', 'Electronics', 'PN junction', 'easy', 'PMDC MDCAT 2025 Physics 13.2', 'A PN junction diode is forward biased when', '["the p-side is connected to the positive terminal and the n-side to the negative terminal", "the p-side is connected to the negative terminal", "both sides are connected to the positive terminal", "no battery is connected"]', 0, 'In forward bias the applied voltage opposes the junction barrier; the depletion layer narrows and a large current flows once about 0.7 V (silicon) is exceeded.', '{"1": "That is reverse bias.", "2": "This applies no voltage across the junction.", "3": "With no supply the diode is unbiased."}'),
  ('PHY-6071', 'Electronics', 'PN junction', 'moderate', 'PMDC MDCAT 2025 Physics 13.2', 'When a PN junction is reverse biased,', '["the depletion region becomes narrower and a large current flows", "the diode conducts in both directions", "the barrier potential disappears", "the depletion region becomes wider and only a very small leakage current flows"]', 3, 'Reverse bias pulls majority carriers away from the junction, widening the depletion layer; only a tiny current due to minority carriers flows.', '{"0": "This describes forward bias.", "1": "A diode conducts well in one direction only.", "2": "The barrier is increased, not removed."}'),
  ('PHY-6072', 'Electronics', 'PN junction', 'moderate', 'PMDC MDCAT 2025 Physics 13.2', 'The depletion region of a PN junction', '["contains many free electrons and holes", "is a region of high conductivity", "contains immobile charged ions and almost no free charge carriers", "exists only in forward bias"]', 2, 'At the junction, electrons and holes recombine, leaving fixed positive donor ions on the n-side and negative acceptor ions on the p-side; their field forms the barrier potential.', '{"0": "Free carriers have recombined in this region.", "1": "Lacking carriers, it behaves almost as an insulator.", "3": "It exists even with no bias; bias only changes its width."}'),
  ('PHY-6073', 'Modern and nuclear physics', 'Nature of radioactive decay', 'moderate', 'PMDC MDCAT 2025 Physics 16.2; NUMS MDCAT 2026 Physics 13.2', 'Which statement about radioactive decay is correct?', '["Heating a radioactive sample speeds up its decay greatly.", "Decay is spontaneous and is not affected by temperature, pressure or chemical combination.", "The decay rate increases at high pressure.", "A radioactive element stops decaying when it forms a compound."]', 1, 'Decay is a nuclear process; external physical and chemical conditions that affect electrons do not change the rate.', '{"0": "Temperature has no measurable effect on decay rate.", "2": "Pressure has no effect.", "3": "Chemical bonding involves electrons, not the nucleus."}'),
  ('PHY-6074', 'Modern and nuclear physics', 'Nature of radioactive decay', 'moderate', 'PMDC MDCAT 2025 Physics 16.2; NUMS MDCAT 2026 Physics 13.2', 'Radioactive decay is described as random because', '["it is impossible to predict which nucleus will decay next or when; only the probability of decay per unit time (the decay constant) is fixed", "all nuclei decay at the same moment", "the half-life changes randomly", "decay depends on the size of the sample"]', 0, 'Each nucleus has a fixed probability of decaying per second, λ. For large numbers this gives a predictable rate (A = λN) even though individual decays are unpredictable.', '{"1": "Nuclei decay at different, unpredictable times.", "2": "The half-life of a nuclide is constant.", "3": "The probability per nucleus is the same for any sample size."}'),
  ('PHY-6075', 'Force and motion', 'Inelastic collision in two dimensions', 'moderate', 'Physics 11 (PECTAA, Punjab), Ch. 2 Force and Motion, p. 42 (§2.11)', 'Two bodies moving in an xy-plane collide and stick together. Which quantities are conserved?', '["Kinetic energy only", "Momentum along x only", "Neither momentum nor kinetic energy", "Momentum along x and momentum along y, but not kinetic energy"]', 3, 'In any collision without external forces, momentum is conserved in each direction separately; in a perfectly inelastic collision some kinetic energy is lost.', '{"0": "Kinetic energy is not conserved when bodies stick together.", "1": "Momentum is conserved along y as well.", "2": "Momentum is always conserved in an isolated collision."}'),
  ('PHY-6076', 'Force and motion', 'Inelastic collision in two dimensions', 'hard', 'Physics 11 (PECTAA, Punjab), Ch. 2 Force and Motion, p. 42 (§2.11)', 'A 2 kg ball moving along +x at 3 m s⁻¹ collides with a 1 kg ball moving along +y at 6 m s⁻¹, and they stick together. The speed of the combined mass is about', '["2.0 m s⁻¹", "3.0 m s⁻¹", "2.8 m s⁻¹", "4.0 m s⁻¹"]', 2, 'pₓ = 2 × 3 = 6 kg m s⁻¹ and p_y = 1 × 6 = 6 kg m s⁻¹, so p = √72 ≈ 8.49 kg m s⁻¹; v = 8.49/3 ≈ 2.8 m s⁻¹ at 45° to the x-axis.', '{"0": "This uses only the x-momentum.", "1": "This adds the speeds and averages them.", "3": "This adds the two momenta as if they were along one line (12/3 = 4.0 m s⁻¹); they are at right angles."}'),
  ('PHY-6077', 'Waves', 'Doppler effect for light', 'moderate', 'Physics 11 (PECTAA, Punjab), Ch. 7 Waves and Vibrations, p. 162 (Example 7.12)', 'A spectral line measured at 397 nm in the laboratory is observed at 478 nm in the light from a distant galaxy. This shows that the galaxy is', '["moving towards the Earth", "moving away from the Earth (red shift)", "at rest relative to the Earth", "getting hotter"]', 1, 'A longer observed wavelength (lower frequency) means the source is receding; this is the red shift used to show the universe is expanding.', '{"0": "An approaching source shows a blue shift (shorter wavelength).", "2": "A stationary source would show no shift.", "3": "The Doppler shift tells us about motion, not temperature."}'),
  ('PHY-6078', 'Waves', 'Applications of the Doppler effect', 'easy', 'Physics 11 (PECTAA, Punjab), Ch. 7 Waves and Vibrations, p. 162 (Example 7.12)', 'Doppler echocardiography and Doppler ultrasound are used in medicine to', '["measure the speed of blood flow and detect narrowed or leaking valves and vessels", "measure body temperature", "take X-ray images of bones", "measure blood sugar"]', 0, 'Ultrasound reflected from moving blood cells changes frequency; the shift gives the blood flow velocity, revealing stenosis or regurgitation.', '{"1": "Temperature is measured with thermometers.", "2": "X-ray imaging does not use the Doppler effect.", "3": "Blood sugar is measured chemically."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-6001', 'Reproduction', 'Sexually transmitted diseases', 'easy', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 8.3; NUMS MDCAT 2026 Biology 11.3', 'Gonorrhoea is caused by', '["Treponema pallidum", "Neisseria gonorrhoeae", "Herpes simplex virus", "Chlamydia trachomatis"]', 1, 'Gonorrhoea is a bacterial STD caused by Neisseria gonorrhoeae, a Gram-negative diplococcus.', '{"0": "Treponema pallidum causes syphilis.", "2": "Herpes simplex virus causes genital herpes.", "3": "Chlamydia trachomatis causes chlamydia."}'),
  ('BIO-6002', 'Reproduction', 'Sexually transmitted diseases', 'easy', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 8.3; NUMS MDCAT 2026 Biology 11.3', 'The causative agent of syphilis is', '["a spirochaete bacterium, Treponema pallidum", "a virus", "a protozoan", "a fungus"]', 0, 'Syphilis is caused by Treponema pallidum, a thin spiral (spirochaete) bacterium.', '{"1": "Syphilis is bacterial; viral STDs include herpes and AIDS.", "2": "Trichomoniasis, not syphilis, is caused by a protozoan.", "3": "Fungi do not cause syphilis."}'),
  ('BIO-6003', 'Reproduction', 'Sexually transmitted diseases', 'moderate', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 8.3; NUMS MDCAT 2026 Biology 11.3', 'The first (primary) sign of syphilis is usually', '["painful blisters that keep coming back", "a pus-like discharge with burning urination", "damage to the heart and brain", "a painless sore (chancre) at the site of infection"]', 3, 'Primary syphilis produces a firm, painless ulcer called a chancre. A skin rash follows in the secondary stage; untreated, the tertiary stage can damage the heart, brain and other organs years later.', '{"0": "Recurring painful blisters are typical of genital herpes.", "1": "Discharge with burning urination is typical of gonorrhoea.", "2": "Heart and brain damage occur in late (tertiary) syphilis."}'),
  ('BIO-6004', 'Reproduction', 'Sexually transmitted diseases', 'moderate', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 8.3; NUMS MDCAT 2026 Biology 11.3', 'Which sexually transmitted disease is caused by a virus and cannot be cured with antibiotics?', '["Gonorrhoea", "Syphilis", "Genital herpes", "Chlamydia"]', 2, 'Genital herpes is caused by herpes simplex virus (mostly HSV-2). Antibiotics act on bacteria, not viruses; antiviral drugs can only control outbreaks.', '{"0": "Gonorrhoea is bacterial and treatable with antibiotics.", "1": "Syphilis is bacterial and treatable with penicillin.", "3": "Chlamydia is bacterial and treatable with antibiotics."}'),
  ('BIO-6005', 'Reproduction', 'Sexually transmitted diseases', 'hard', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 8.3; NUMS MDCAT 2026 Biology 11.3', 'Painful blisters of genital herpes heal but keep recurring months later, because the virus', '["is killed and the person is reinfected each time", "stays dormant (latent) in sensory nerve cells and becomes active again", "lives permanently in the blood", "forms spores in the skin"]', 1, 'After the first infection herpes simplex virus remains latent in the sensory nerve ganglia and can be reactivated by stress or illness, causing new outbreaks.', '{"0": "Recurrence happens without reinfection.", "2": "The virus hides in nerve ganglia, not freely in blood.", "3": "Viruses do not form spores."}'),
  ('BIO-6006', 'Reproduction', 'Sexually transmitted diseases', 'moderate', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 8.3; NUMS MDCAT 2026 Biology 11.3', 'A man has burning pain on urination and a thick yellowish discharge. A smear shows Gram-negative diplococci. The most likely diagnosis is', '["gonorrhoea", "syphilis", "genital herpes", "AIDS"]', 0, 'Painful urination with purulent urethral discharge and Gram-negative diplococci (Neisseria gonorrhoeae) are typical of gonorrhoea. In women it is often symptomless and can cause infertility if untreated.', '{"1": "Syphilis begins with a painless sore and is caused by a spirochaete.", "2": "Herpes causes blisters and is viral.", "3": "AIDS does not cause these local symptoms."}'),
  ('BIO-6007', 'Reproduction', 'Sexually transmitted diseases', 'easy', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 8.3; NUMS MDCAT 2026 Biology 11.3', 'HIV, the virus that causes AIDS, is NOT spread by', '["unprotected sexual contact", "sharing used needles", "an infected mother to her baby", "shaking hands or mosquito bites"]', 3, 'HIV spreads through body fluids such as semen, vaginal fluid, blood and breast milk. It is not spread by casual contact, sharing food or utensils, or insect bites.', '{"0": "Sexual contact is the main route of HIV transmission.", "1": "Shared needles transfer infected blood.", "2": "HIV can pass across the placenta, at birth or in breast milk."}'),
  ('BIO-6008', 'Reproduction', 'Sexually transmitted diseases', 'moderate', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 8.3; NUMS MDCAT 2026 Biology 11.3', 'Chlamydia, one of the most common bacterial STDs, is dangerous mainly because', '["it is caused by a virus", "it cannot be treated", "it often produces no symptoms, yet if untreated can block the oviducts and cause infertility", "it spreads through air"]', 2, 'Chlamydia trachomatis infections are frequently silent, especially in women, and can lead to pelvic inflammatory disease and tubal infertility; they are curable with antibiotics.', '{"0": "Chlamydia trachomatis is a bacterium.", "1": "It is curable with antibiotics such as tetracyclines.", "3": "It is transmitted sexually, not through air."}'),
  ('BIO-6009', 'Cell structure and function', 'Animal and plant cells', 'moderate', 'PMDC MDCAT 2025 Biology 4.1; NUMS MDCAT 2026 Biology 4.1', 'Which structure is found in a typical animal cell but NOT in the cells of flowering plants?', '["Mitochondria", "Centrioles", "Golgi apparatus", "Ribosomes"]', 1, 'Animal cells have a pair of centrioles in the centrosome; cells of higher plants lack centrioles and form spindles without them.', '{"0": "Both plant and animal cells have mitochondria.", "2": "Both have Golgi apparatus.", "3": "All cells have ribosomes."}'),
  ('BIO-6010', 'Cell structure and function', 'Animal and plant cells', 'easy', 'PMDC MDCAT 2025 Biology 4.1; NUMS MDCAT 2026 Biology 4.1', 'Which features are found in a typical plant cell but not in an animal cell?', '["Cellulose cell wall, chloroplasts and a large central vacuole", "Cell membrane and nucleus", "Mitochondria and ribosomes", "Centrioles and lysosomes"]', 0, 'Plant cells have a rigid cellulose wall, chloroplasts for photosynthesis and usually a large permanent vacuole; animal cells lack these.', '{"1": "All eukaryotic cells have these.", "2": "Both cell types have mitochondria and ribosomes.", "3": "Centrioles are typical of animal cells."}'),
  ('BIO-6011', 'Cell structure and function', 'Animal and plant cells', 'easy', 'PMDC MDCAT 2025 Biology 4.1; NUMS MDCAT 2026 Biology 4.1', 'The main storage carbohydrate in plant cells and in animal cells respectively is', '["glycogen and starch", "cellulose and starch", "sucrose and cellulose", "starch and glycogen"]', 3, 'Plants store glucose as starch (in plastids); animals store it as glycogen, mainly in liver and muscle.', '{"0": "This is reversed.", "1": "Cellulose is a structural polysaccharide, and animals do not store starch.", "2": "Cellulose is not a storage carbohydrate."}'),
  ('BIO-6012', 'Cell structure and function', 'Animal and plant cells', 'moderate', 'PMDC MDCAT 2025 Biology 4.1; NUMS MDCAT 2026 Biology 4.1', 'Plant cells usually have a fixed, regular shape while animal cells are often rounded or irregular. This is mainly because plant cells have', '["a nucleus", "more mitochondria", "a rigid cell wall outside the cell membrane", "no cytoskeleton"]', 2, 'The cellulose cell wall gives plant cells a definite shape and resists bursting; animal cells, bounded only by a flexible membrane, can change shape.', '{"0": "Both have nuclei.", "1": "Mitochondria do not determine cell shape.", "3": "Plant cells do have a cytoskeleton."}'),
  ('BIO-6013', 'Cell structure and function', 'Fluid mosaic model', 'moderate', 'PMDC MDCAT 2025 Biology 4.3; NUMS MDCAT 2026 Biology 4.4', 'In the fluid mosaic model of the cell membrane, the word "fluid" refers to the fact that', '["the membrane is made of water", "phospholipids and many proteins can move sideways within the bilayer", "the membrane has no fixed thickness", "proteins are dissolved in the cytoplasm"]', 1, 'The lipid bilayer behaves like a two-dimensional liquid in which lipid and protein molecules drift laterally; "mosaic" describes the proteins scattered through it.', '{"0": "The membrane is made of lipids and proteins, not water.", "2": "Membrane thickness is fairly constant (about 7–10 nm).", "3": "Membrane proteins are embedded in the bilayer."}'),
  ('BIO-6014', 'Cell structure and function', 'Fluid mosaic model', 'moderate', 'PMDC MDCAT 2025 Biology 4.3; NUMS MDCAT 2026 Biology 4.4', 'In animal cell membranes, cholesterol molecules wedged between the phospholipids', '["regulate membrane fluidity and add stability", "carry glucose into the cell", "act as receptors for hormones", "store energy"]', 0, 'Cholesterol prevents the membrane from becoming too fluid at body temperature and too rigid at low temperatures.', '{"1": "Carrier proteins, not cholesterol, transport glucose.", "2": "Receptors are usually glycoproteins.", "3": "Energy is stored as fats and glycogen, not membrane cholesterol."}'),
  ('BIO-6015', 'Cell structure and function', 'Fluid mosaic model', 'moderate', 'PMDC MDCAT 2025 Biology 4.3; NUMS MDCAT 2026 Biology 4.4', 'Glycoproteins and glycolipids on the outer surface of the cell membrane mainly function in', '["photosynthesis", "DNA replication", "ATP synthesis", "cell recognition and binding of signals"]', 3, 'Their carbohydrate chains form the glycocalyx, which acts as identification markers (e.g. blood groups) and receptor sites for hormones and other signals.', '{"0": "Photosynthesis occurs in chloroplasts.", "1": "DNA replication occurs in the nucleus.", "2": "ATP is made mainly in mitochondria."}'),
  ('BIO-6016', 'Evolution', 'Origin of life', 'moderate', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 7.1; NUMS MDCAT 2026 Biology 8.1', 'According to the Oparin–Haldane hypothesis, the first life arose', '["by special creation", "from spores that came from other planets", "by gradual chemical evolution of organic molecules from simple inorganic substances in the early Earth''s atmosphere and oceans", "spontaneously from rotting meat"]', 2, 'Oparin and Haldane proposed that energy (lightning, UV) acting on a reducing atmosphere formed organic molecules, which collected in the seas ("primordial soup") and gradually gave rise to the first cells.', '{"0": "Special creation is not a scientific hypothesis of chemical origin.", "1": "This is the panspermia idea.", "3": "Spontaneous generation from meat was disproved by Redi and Pasteur."}'),
  ('BIO-6017', 'Evolution', 'Origin of life', 'moderate', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 7.1; NUMS MDCAT 2026 Biology 8.1', 'In the Miller–Urey experiment (1953), electric sparks passed through a mixture of methane, ammonia, hydrogen and water vapour produced', '["living bacteria", "amino acids and other simple organic compounds", "DNA", "oxygen gas"]', 1, 'The experiment showed that organic molecules such as amino acids can form from inorganic gases under conditions thought to resemble the early Earth.', '{"0": "No living cells were formed.", "2": "DNA, a complex polymer, was not produced.", "3": "The mixture had no free oxygen, and none was produced."}'),
  ('BIO-6018', 'Evolution', 'Origin of life', 'easy', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 7.1; NUMS MDCAT 2026 Biology 8.1', 'The early atmosphere of the Earth, in which organic molecules are thought to have formed, lacked', '["free oxygen (O₂)", "water vapour", "methane", "ammonia"]', 0, 'The primitive atmosphere was reducing. Free oxygen would have broken down the newly formed organic molecules; O₂ accumulated later from photosynthesis.', '{"1": "Water vapour was present.", "2": "Methane is thought to have been present.", "3": "Ammonia is thought to have been present."}'),
  ('BIO-6019', 'Evolution', 'Origin of life', 'moderate', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 7.1; NUMS MDCAT 2026 Biology 8.1', 'Coacervates (protobionts) are considered possible forerunners of cells because they', '["contain DNA and divide by mitosis", "are fossils of the first bacteria", "carry out photosynthesis", "are droplets of organic molecules enclosed by a boundary that keeps an internal environment different from the surroundings"]', 3, 'Coacervates form spontaneously from mixtures of organic polymers in water; they have a membrane-like boundary, can absorb substances and grow, resembling simple cells.', '{"0": "They lack genetic material and true cell division.", "1": "They are laboratory droplets, not fossils.", "2": "They cannot photosynthesise."}'),
  ('BIO-6020', 'Evolution', 'Origin of life', 'hard', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 7.1; NUMS MDCAT 2026 Biology 8.1', 'Many scientists think RNA, rather than DNA or protein, was the first genetic molecule because RNA', '["is double stranded and very stable", "contains thymine", "can both store genetic information and act as a catalyst (ribozyme)", "is made only in the nucleus"]', 2, 'The "RNA world" idea: some RNA molecules can copy information and catalyse reactions, so RNA could have served both roles before DNA and enzymes evolved.', '{"0": "RNA is usually single stranded and less stable than DNA.", "1": "RNA contains uracil, not thymine.", "3": "The first molecules existed before nuclei."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Biology', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('BIO-6021', 'Biotechnology', 'Vaccines from biotechnology', 'moderate', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 16.1', 'The modern hepatitis B vaccine is made by', '["killing hepatitis B viruses with heat", "inserting the gene for the virus''s surface protein (HBsAg) into yeast, which then produces the protein used in the vaccine", "growing the virus in eggs", "extracting antibodies from infected people"]', 1, 'This recombinant (subunit) vaccine contains only the viral surface antigen made by genetically engineered yeast; it stimulates immunity without any live virus.', '{"0": "This vaccine is not made from whole killed virus.", "2": "Egg-grown viruses are used for some influenza vaccines.", "3": "Antibodies from people give passive, not vaccine-induced, immunity."}'),
  ('BIO-6022', 'Biotechnology', 'Vaccines from biotechnology', 'moderate', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 16.1', 'A major advantage of recombinant subunit vaccines over vaccines made from weakened whole pathogens is that they', '["cannot cause the disease, because they contain only a harmless part of the pathogen and no genetic material that can replicate", "need no injection", "give lifelong immunity after one dose in every case", "work against all diseases"]', 0, 'Because only a purified antigen is used, there is no risk of the vaccine strain reverting to a harmful form; booster doses may still be needed.', '{"1": "Most subunit vaccines are injected.", "2": "Boosters are often needed.", "3": "Each vaccine is specific to one pathogen."}'),
  ('BIO-6023', 'Biotechnology', 'Vaccines from biotechnology', 'moderate', 'Standard topic not in the PECTAA Biology books; PMDC MDCAT 2025 Biology 16.1', 'mRNA vaccines, such as those used against COVID-19, work by', '["injecting live virus", "changing the person''s DNA permanently", "supplying ready-made antibodies", "delivering mRNA that instructs the body''s own cells to make a viral protein, which then triggers an immune response"]', 3, 'The mRNA (in lipid nanoparticles) is translated into the spike protein; the immune system learns to recognise it. The mRNA is broken down and does not enter the nucleus or alter DNA.', '{"0": "No virus is present in an mRNA vaccine.", "1": "mRNA does not integrate into DNA.", "2": "Ready-made antibodies give passive immunity; vaccines give active immunity."}'),
  ('BIO-6024', 'Acellular life', 'Discovery of viruses', 'moderate', 'Standard topic not in the PECTAA Biology books; NUMS MDCAT 2026 Biology 1.1', 'In 1892, Ivanovsky found that sap from tobacco plants with mosaic disease remained infectious even after it had been passed through a filter that holds back bacteria. This showed that', '["the disease was caused by a fungus", "the disease was not infectious", "the infectious agent was smaller than bacteria", "bacteria can pass through any filter"]', 2, 'The agent passed through a bacteria-proof (porcelain) filter, so it had to be smaller than bacteria; it was later identified as tobacco mosaic virus.', '{"0": "Fungi are larger than bacteria and would be filtered out.", "1": "The filtered sap still caused disease.", "3": "The filter did hold back bacteria."}'),
  ('BIO-6025', 'Acellular life', 'Discovery of viruses', 'moderate', 'Standard topic not in the PECTAA Biology books; NUMS MDCAT 2026 Biology 1.1', 'Who described the filterable agent of tobacco mosaic disease as a "contagium vivum fluidum" (contagious living fluid) and used the term virus for it?', '["Pasteur", "Beijerinck", "Stanley", "Leeuwenhoek"]', 1, 'Martinus Beijerinck (1898) repeated the filtration experiments and concluded the agent was a new kind of infectious agent that multiplied only in living cells.', '{"0": "Pasteur worked on rabies and germ theory but did not describe TMV this way.", "2": "Stanley crystallised TMV in 1935.", "3": "Leeuwenhoek first observed bacteria with a microscope."}'),
  ('BIO-6026', 'Acellular life', 'Discovery of viruses', 'moderate', 'Standard topic not in the PECTAA Biology books; NUMS MDCAT 2026 Biology 1.1', 'W. M. Stanley (1935) showed that tobacco mosaic virus could be', '["crystallised, yet remained infectious", "grown on nutrient agar", "seen with a light microscope", "killed by antibiotics"]', 0, 'Stanley crystallised TMV, showing that viruses can behave like chemicals outside cells while still being able to infect; he shared the 1946 Nobel Prize.', '{"1": "Viruses cannot multiply on non-living media.", "2": "TMV is too small to be resolved by a light microscope.", "3": "Antibiotics do not affect viruses."}'),
  ('BIO-6027', 'Bioenergetics', 'Factors affecting photosynthesis', 'moderate', 'NUMS MDCAT 2026 Biology 2.2', 'As light intensity increases, the rate of photosynthesis rises at first and then levels off. In the level part of the curve, the rate is most likely limited by', '["light intensity", "the amount of chlorophyll only", "oxygen concentration", "carbon dioxide concentration or temperature"]', 3, 'By the law of limiting factors, once light is plentiful another factor in short supply, usually CO₂ concentration or temperature, controls the rate.', '{"0": "More light no longer increases the rate, so light is not limiting.", "1": "Chlorophyll is rarely the factor that changes; CO₂ and temperature are typical limits.", "2": "Oxygen is a product, not a limiting reactant."}'),
  ('BIO-6028', 'Bioenergetics', 'Factors affecting photosynthesis', 'moderate', 'NUMS MDCAT 2026 Biology 2.2', 'The light intensity at which the rate of photosynthesis exactly equals the rate of respiration, so there is no net exchange of CO₂ or O₂, is called the', '["saturation point", "limiting point", "compensation point", "photoperiod"]', 2, 'At dawn and dusk light is dim; at the compensation point the CO₂ released by respiration is used exactly by photosynthesis.', '{"0": "At the saturation point more light gives no further increase in rate.", "1": "This is not a standard term.", "3": "Photoperiod is the length of the daily light period."}'),
  ('BIO-6029', 'Bioenergetics', 'Factors affecting photosynthesis', 'easy', 'NUMS MDCAT 2026 Biology 2.2', 'Growers often raise the CO₂ concentration inside greenhouses because', '["CO₂ cools the plants", "CO₂ is often the limiting factor for photosynthesis in bright light, so more CO₂ increases growth", "CO₂ kills pests", "plants absorb CO₂ through their roots"]', 1, 'Atmospheric CO₂ (about 0.04%) frequently limits photosynthesis when light and temperature are adequate; enriching it raises the rate and yield.', '{"0": "CO₂ enrichment does not cool plants.", "2": "This is not the purpose of CO₂ enrichment.", "3": "CO₂ enters leaves through stomata."}'),
  ('BIO-6030', 'Bioenergetics', 'Factors affecting photosynthesis', 'moderate', 'NUMS MDCAT 2026 Biology 2.2', 'During a drought the rate of photosynthesis falls mainly because', '["the stomata close to save water, so less CO₂ enters the leaf", "water is the only raw material that runs out", "chlorophyll dissolves", "light cannot reach the leaves"]', 0, 'Only a tiny fraction of absorbed water is used in photosynthesis. Water stress closes the stomata, cutting the supply of CO₂ to the chloroplasts.', '{"1": "The direct need for water in photosynthesis is small.", "2": "Chlorophyll does not dissolve.", "3": "Light is unaffected by drought."}'),
  ('BIO-6031', 'Bioenergetics', 'Cyclic and non-cyclic photophosphorylation', 'moderate', 'NUMS MDCAT 2026 Biology 2.3–2.4', 'Cyclic photophosphorylation differs from the non-cyclic pathway because it', '["involves only photosystem II", "splits water and releases oxygen", "makes NADPH but no ATP", "involves only photosystem I and makes ATP but no NADPH or oxygen"]', 3, 'In the cyclic pathway, electrons from P700 return to photosystem I through the electron transport chain, producing ATP only; water is not split.', '{"0": "Photosystem II takes part in the non-cyclic pathway.", "1": "Water splitting occurs only in the non-cyclic pathway.", "2": "Cyclic flow makes ATP, not NADPH."}'),
  ('BIO-6032', 'Bioenergetics', 'Cyclic and non-cyclic photophosphorylation', 'moderate', 'NUMS MDCAT 2026 Biology 2.3–2.4', 'In non-cyclic photophosphorylation, the electrons lost by photosystem II are replaced by electrons from', '["NADPH", "carbon dioxide", "water", "glucose"]', 2, 'Photolysis of water (2H₂O → 4H⁺ + 4e⁻ + O₂) supplies electrons to P680; the oxygen is released as a by-product.', '{"0": "NADPH is a final product of the pathway.", "1": "CO₂ is used in the Calvin cycle.", "3": "Glucose is made later, not used here."}'),
  ('BIO-6033', 'Bioenergetics', 'Cyclic and non-cyclic photophosphorylation', 'hard', 'NUMS MDCAT 2026 Biology 2.3–2.4', 'Chloroplasts run cyclic photophosphorylation alongside the non-cyclic pathway mainly because', '["cyclic flow produces oxygen", "the Calvin cycle needs more ATP than NADPH (3 ATP : 2 NADPH per CO₂), and cyclic flow supplies the extra ATP", "cyclic flow makes glucose directly", "non-cyclic flow cannot make any ATP"]', 1, 'Non-cyclic flow gives roughly equal amounts of ATP and NADPH, but fixing each CO₂ needs 3 ATP and 2 NADPH; cyclic flow makes up the ATP shortfall.', '{"0": "Cyclic flow does not split water or release O₂.", "2": "Glucose is made in the Calvin cycle.", "3": "Non-cyclic flow does produce ATP."}'),
  ('BIO-6034', 'Plant physiology', 'Carnivorous plants', 'moderate', 'NUMS MDCAT 2026 Biology 9.1', 'Carnivorous plants such as the pitcher plant are best described as', '["green autotrophs that obtain extra nitrogen and minerals by digesting insects, as they grow in nutrient-poor soil", "heterotrophs that cannot photosynthesise", "parasites on other plants", "decomposers of dead leaves"]', 0, 'They have chlorophyll and make their own food, but trap and digest insects to supplement nitrogen in boggy, nitrogen-deficient soils.', '{"1": "They are green and photosynthesise.", "2": "They do not take food from another plant.", "3": "They actively trap living insects."}'),
  ('BIO-6035', 'Biological molecules', 'Fibrous and globular proteins', 'easy', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules, p. 113 (Table 4.4)', 'Which of these is a globular protein?', '["Keratin", "Collagen", "Fibrin", "Haemoglobin"]', 3, 'Haemoglobin is a soluble, functional, roughly spherical protein. Keratin, collagen and fibrin are fibrous, structural proteins.', '{"0": "Keratin of hair and nails is fibrous.", "1": "Collagen of connective tissue is fibrous.", "2": "Fibrin of blood clots is fibrous."}'),
  ('BIO-6036', 'Biological molecules', 'Fibrous and globular proteins', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 4 Biomolecules, p. 113 (Table 4.4)', 'Compared with globular proteins, fibrous proteins are', '["soluble and act mainly as enzymes", "easily crystallised", "insoluble, mainly structural and not easily disorganised", "spherical in shape"]', 2, 'Fibrous proteins form fibrils with mainly primary/secondary structure, are insoluble, elastic, non-crystalline and stable, and play structural roles.', '{"0": "Solubility and enzyme activity are features of globular proteins.", "1": "Globular proteins, not fibrous ones, can be crystallised.", "3": "Globular proteins are spherical or ellipsoidal."}'),
  ('BIO-6037', 'Enzymes', 'Classification of enzymes', 'easy', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes, p. 138 (Classification on the basis of substrates)', 'When enzymes are classified by their substrates, sucrase, maltase and cellulase all belong to the group', '["proteases", "carbohydrases", "lipases", "nucleases"]', 1, 'Carbohydrases break larger carbohydrates into smaller units: sucrase (sucrose), maltase (maltose), cellulase (cellulose), amylase (starch).', '{"0": "Proteases act on proteins.", "2": "Lipases act on lipids.", "3": "Nucleases act on nucleic acids."}'),
  ('BIO-6038', 'Enzymes', 'Classification of enzymes', 'moderate', 'Biology 11 (PECTAA, Punjab), Ch. 5 Enzymes, p. 138 (Classification on the basis of substrates)', 'In the digestion of proteins, the enzyme erypsin breaks', '["dipeptides into amino acids", "large polypeptides into smaller polypeptides", "starch into maltose", "lipids into fatty acids and glycerol"]', 0, 'Pepsin and trypsin split large polypeptides, aminopeptidases produce dipeptides, and erypsin completes protein digestion by breaking dipeptides into amino acids.', '{"1": "This is done by pepsin and trypsin.", "2": "This is done by amylase.", "3": "This is done by lipase."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

